def set_category_top_value(df, category):
    """Set the top value in category to somewhere within the category cap range"""
    cat_indices = df[df['Column'] == category].index
    if len(cat_indices) == 0:
        return df
    
    # Ensure Percentage column is numeric for this category
    df.loc[cat_indices, 'Percentage'] = pd.to_numeric(df.loc[cat_indices, 'Percentage'], errors='coerce')
    
    # Get category cap range
    category_caps = get_category_caps()
    category_min, category_max = category_caps.get(category.lower(), (10, 50))
    
    # Set top value near the maximum cap (higher for large categories)
    range_size = category_max - category_min
    
    # Check category size to determine top value strategy
    cat_size = len(cat_indices)
    if cat_size > 100:  # Large categories like INTEREST - use much higher top values
        # For large categories, use close to the absolute maximum to maintain strong hierarchy
        min_top = category_max * 0.85  # 85% of maximum cap
        max_top = category_max * 0.98  # 98% of maximum cap
        print(f"    🎯 Large category ({cat_size} items): Setting VERY HIGH top value ({min_top:.1f}% - {max_top:.1f}%)")
    else:  # Smaller categories
        min_top = category_min + (range_size * 0.85)  # 85% into the range
        max_top = category_min + (range_size * 0.98)  # 98% into the range (near max cap)
    
    new_top_value = np.random.uniform(min_top, max_top)
    
    # Find current top value and set it
    top_idx = df.loc[cat_indices, 'Percentage'].idxmax()
    df.at[top_idx, 'Percentage'] = new_top_value
    
    return df

def create_smooth_cascade(df, category):
    """Create cascade from top value down to near 0, keeping original order"""
    cat_indices = df[df['Column'] == category].index
    if len(cat_indices) <= 1:
        return df
    
    # Get current order and find the top value
    cat_df = df.loc[cat_indices].copy()
    
    # Ensure Percentage column is numeric
    cat_df['Percentage'] = pd.to_numeric(cat_df['Percentage'], errors='coerce')
    
    # Sort by current percentage to maintain hierarchy
    sorted_indices = cat_df.sort_values('Percentage', ascending=False).index
    
    # Get the top value (already set by set_category_top_value)
    top_value = df.at[sorted_indices[0], 'Percentage']
    
    # Create smooth exponential decay from top to minimum
    num_items = len(sorted_indices)
    if num_items == 1:
        return df
    
    # Create decay factors: MULTI-TIER CASCADE with concentrated high-value clusters
    if num_items > 100:  # Large categories like INTEREST - create multiple high-value tiers
        # SMART TARGETING: Design cascade to fit within category cap (avoid scaling destruction)
        # Get the category cap to target the right total
        category_caps = get_category_caps()
        category_min, category_max = category_caps.get(category.lower(), (35, 55))
        target_total = category_max * 0.95  # Target 95% of max cap
        
        # Calculate decay factors that will sum to approximately the target total
        decay_factors = np.ones(num_items)
        
        # Tier 1: Top 5 items (high concentration)
        tier1_factors = np.random.uniform(0.15, 0.25, min(5, num_items))  # 15-25% of total each
        
        # Tier 2: Next 15 items (medium-high concentration)
        tier2_factors = np.random.uniform(0.08, 0.15, min(15, num_items-5))  # 8-15% of total each
        
        # Tier 3: Next 30 items (medium concentration)  
        tier3_factors = np.random.uniform(0.03, 0.08, min(30, num_items-20))  # 3-8% of total each
        
        # Tier 4: Next 50 items (low concentration)
        tier4_factors = np.random.uniform(0.01, 0.03, min(50, num_items-50))  # 1-3% of total each
        
        # Tier 5: Remaining items (very low)
        remaining = max(0, num_items - 100)
        if remaining > 0:
            tier5_factors = np.random.uniform(0.005, 0.01, remaining)  # 0.5-1% of total each
        
        # Combine all tiers
        all_factors = []
        all_factors.extend(tier1_factors[:min(5, num_items)])
        if num_items > 5:
            all_factors.extend(tier2_factors[:min(15, num_items-5)])
        if num_items > 20:
            all_factors.extend(tier3_factors[:min(30, num_items-20)])
        if num_items > 50:
            all_factors.extend(tier4_factors[:min(50, num_items-50)])
        if num_items > 100:
            all_factors.extend(tier5_factors[:remaining])
        
        # Normalize to target total
        current_sum = sum(all_factors)
        scale_factor = target_total / current_sum
        decay_factors = np.array(all_factors) * scale_factor
        
        print(f"    🌊 Large category ({num_items} items): SMART MULTI-TIER targeting {target_total:.1f}% total")
    elif num_items > 50:  # Medium categories - moderate decay  
        decay_factors = np.logspace(0, -1.5, num=num_items)  # From 1.0 to ~0.03
        print(f"    🌊 Medium category ({num_items} items): Using moderate decay")
    else:  # Small categories - steeper decay is fine
        decay_factors = np.logspace(0, -2.5, num=num_items)  # From 1.0 to ~0.003
        print(f"    🌊 Small category ({num_items} items): Using steep decay")
    
    # Apply decay cascade using the decay factors
    if num_items > 100:
        # For large categories, decay_factors are already the final percentages
        for i, idx in enumerate(sorted_indices):
            new_value = decay_factors[i]
            # Ensure minimum of 0.01% for non-zero values
            new_value = max(new_value, 0.01)
            df.at[idx, 'Percentage'] = new_value
    else:
        # For smaller categories, normalize and apply to top value
        decay_factors = decay_factors / decay_factors[0]  # Ensure first = 1.0
        for i, idx in enumerate(sorted_indices):
            # Apply the decay factor to the top value
            new_value = top_value * decay_factors[i]
            # Ensure minimum of 0.01% for non-zero values
            new_value = max(new_value, 0.01)
            df.at[idx, 'Percentage'] = new_value
    
    return df

def apply_individual_value_rules(df, category):
    """Apply individual value caps and ordering rules"""
    import numpy as np
    
    cat_indices = df[df['Column'] == category].index
    
    # Ensure Percentage column is numeric for this category
    df.loc[cat_indices, 'Percentage'] = pd.to_numeric(df.loc[cat_indices, 'Percentage'], errors='coerce')
    
    # Get individual brand caps
    individual_caps = get_individual_brand_caps()
    
    # Apply specific positioning rules FIRST (they need to override caps) - CASE INSENSITIVE
    positioning_rules = get_positioning_rules()
    matching_rule = None
    for rule_category in positioning_rules.keys():
        if category.upper() == rule_category.upper():
            matching_rule = positioning_rules[rule_category]
            break
    
    if matching_rule:
        df = apply_positioning_rules(df, category, matching_rule)
    
    # Apply individual brand caps AFTER positioning (but still respect minimums)
    for idx in cat_indices:
        value = df.at[idx, 'Value']
        # Case insensitive matching for individual caps
        value_match = None
        for cap_brand in individual_caps.keys():
            if value.lower() == cap_brand.lower():
                value_match = cap_brand
                break
        
        if value_match:
            min_cap, max_cap = individual_caps[value_match]
            current = float(df.at[idx, 'Percentage'])
            
            # ALWAYS apply individual caps with random values for ALL brands with caps
            # This ensures brands like Hulu, Disney+ get proper values even without positioning rules
            if current < min_cap:
                # Use random value in lower half of cap range
                random_value = np.random.uniform(min_cap, min_cap + (max_cap - min_cap) * 0.5)
            elif current > max_cap:
                # Use random value in upper half of cap range  
                random_value = np.random.uniform(max_cap - (max_cap - min_cap) * 0.5, max_cap)
            else:
                # Value is within range - still apply random value to add jitter and ensure proper distribution
                random_value = np.random.uniform(min_cap, max_cap)
            
            df.at[idx, 'Percentage'] = round(random_value, 4)
    
    return df

def sort_category_descending(df, category):
    """Sort category by percentage from highest to lowest"""
    cat_indices = df[df['Column'] == category].index
    if len(cat_indices) <= 1:
        return df
    
    # Ensure Percentage column is numeric for sorting
    df.loc[cat_indices, 'Percentage'] = pd.to_numeric(df.loc[cat_indices, 'Percentage'], errors='coerce')
    
    # Sort this category by percentage descending
    cat_df = df.loc[cat_indices].sort_values('Percentage', ascending=False)
    
    # Update the main dataframe with sorted order
    df.loc[cat_indices] = cat_df.values
    
    return df

def apply_final_category_cap_enforcement_after_positioning(df):
    """
    Critical final step: Enforce category caps AFTER positioning has been applied.
    This ensures that position boosts don't break category cap limits.
    """
    print("\n🔒 FINAL CATEGORY CAP ENFORCEMENT AFTER POSITIONING")
    print("=" * 60)
    
    # SPECIAL: Force scaling for problematic large categories regardless of previous logic
    force_scale_categories = {
        'INTEREST': (0.01, 0.02),  # SCALED DOWN to 0.01-0.02% range
        'APP/PLATFORM USAGE': (15, 25), 
        'MOST PURCHASED BRANDS': (74, 76),
        'MEDIA': (15, 30),
        'EDUCATION & LEARNING': (2, 3)
    }
    
    for category, (cat_min, cat_max) in force_scale_categories.items():
        category_mask = df['Column'] == category
        if not category_mask.any():
            continue
            
        category_total = df.loc[category_mask, 'Percentage'].sum()
        if category_total > cat_max:
            scale_factor = cat_max / category_total
            print(f"🔧 FORCE SCALING {category}: {category_total:.1f}% → {cat_max:.1f}% (factor: {scale_factor:.3f})")
            
            # Apply aggressive scaling to all values
            for idx in df[category_mask].index:
                current_value = df.at[idx, 'Percentage']
                brand = df.at[idx, 'Value']
                
                # Check if brand has individual cap
                individual_caps = get_individual_brand_caps()
                individual_cap = None
                for cap_brand, (cap_min_ind, cap_max_ind) in individual_caps.items():
                    if brand.lower() == cap_brand.lower():
                        individual_cap = cap_max_ind
                        break
                
                # Scale value but respect individual cap
                new_value = current_value * scale_factor
                if individual_cap and new_value > individual_cap:
                    new_value = individual_cap
                
                df.at[idx, 'Percentage'] = max(0.01, new_value)
    
    # Get all behavioral categories (not demographics)
    behavioral_categories = [cat for cat in df['Column'].unique() 
                           if cat not in ['GENDER', 'AGE', 'ETHNICITY', 'INCOME', 'EDUCATION', 
                                        'RELATIONSHIP', 'SEXUAL_ORIENTATION', 'PARENTAL_STATUS', 'LOCATION',
                                        'SAMPLE SIZE', 'AVID FAN', 'CASUAL FAN']]
    
    # Apply final caps to each category
    for category in behavioral_categories:
        category_mask = df['Column'] == category
        if not category_mask.any():
            continue
            
        category_total = df.loc[category_mask, 'Percentage'].sum()
        
        # Get category caps
        caps = get_category_caps()
        if category.upper() in caps:
            category_min, category_max = caps[category.upper()]
            
            # Only enforce if we're over the maximum
            if category_total > category_max:
                # AGGRESSIVE FINAL SCALING: Force compliance with category caps
                scale_factor = category_max / category_total
                print(f"📊 FINAL SCALING {category}: {category_total:.1f}% → {category_max:.1f}% (scale: {scale_factor:.3f})")
                
                # Apply scaling while respecting individual caps
                for idx in df[category_mask].index:
                    current_value = df.at[idx, 'Percentage']
                    brand = df.at[idx, 'Value']
                    
                    # Check if brand has individual cap
                    individual_caps = get_individual_brand_caps()
                    individual_cap = None
                    for cap_brand, (cap_min, cap_max) in individual_caps.items():
                        if brand.lower() == cap_brand.lower():
                            individual_cap = cap_max
                            break
                    
                    # Scale value but respect individual cap
                    new_value = current_value * scale_factor
                    if individual_cap and new_value > individual_cap:
                        new_value = individual_cap
                    
                    df.at[idx, 'Percentage'] = max(0.01, new_value)
                    
            # SPECIAL HANDLING: If category total is too low (below minimum), boost values
            elif category_total < category_min:
                # For large categories like INTEREST, ensure proper top values
                if len(df[category_mask]) > 100:  # Large categories
                    boost_factor = category_min / category_total
                    print(f"📈 BOOSTING LARGE CATEGORY {category}: {category_total:.1f}% → {category_min:.1f}% (boost: {boost_factor:.3f})")
                    
                    # Boost all values proportionally
                    for idx in df[category_mask].index:
                        current_value = df.at[idx, 'Percentage']
                        new_value = current_value * boost_factor
                        df.at[idx, 'Percentage'] = new_value
    
    # FINAL PASS: Re-apply force scaling after any other adjustments
    print("\n🔧 FINAL FORCE SCALING PASS:")
    for category, (cat_min, cat_max) in force_scale_categories.items():
        category_mask = df['Column'] == category
        if not category_mask.any():
            continue
            
        category_total = df.loc[category_mask, 'Percentage'].sum()
        if category_total > cat_max:
            scale_factor = cat_max / category_total
            print(f"   🎯 FINAL {category}: {category_total:.1f}% → {cat_max:.1f}% (factor: {scale_factor:.3f})")
            
            # Apply final aggressive scaling
            for idx in df[category_mask].index:
                current_value = df.at[idx, 'Percentage']
                brand = df.at[idx, 'Value']
                
                # Check if brand has individual cap
                individual_caps = get_individual_brand_caps()
                individual_cap = None
                for cap_brand, (cap_min_ind, cap_max_ind) in individual_caps.items():
                    if brand.lower() == cap_brand.lower():
                        individual_cap = cap_max_ind
                        break
                
                # Scale value but respect individual cap
                new_value = current_value * scale_factor
                if individual_cap and new_value > individual_cap:
                    new_value = individual_cap
                
                df.at[idx, 'Percentage'] = max(0.01, new_value)
    
    return df

def apply_final_positioning_enforcement(df):
    """
    FINAL PASS: Enforce all positioning rules AFTER everything else is done.
    This ensures positioning is never overridden by subsequent processing.
    """
    
    
    print("\n🎯 FINAL POSITIONING ENFORCEMENT - BULLETPROOF PASS")
    print("=" * 60)
    
    positioning_rules = get_positioning_rules()
    individual_caps = get_individual_brand_caps()
    
    for category, rules in positioning_rules.items():
        # Find category (case insensitive)
        cat_mask = df['Column'].str.upper() == category.upper()
        if not cat_mask.any():
            continue
            
        print(f"📍 Enforcing {category} positioning rules: {rules}")
        
        for rule_type, required_brands in rules.items():
            if rule_type == 'top_1':
                target_positions = 1
            elif rule_type == 'top_2':
                target_positions = 2
            elif rule_type == 'top_3':
                target_positions = 3
            elif rule_type == 'top_4':
                target_positions = 4
            elif rule_type == 'top_5':
                target_positions = 5
            elif rule_type == 'top_5':
                target_positions = 5
            elif rule_type == 'top_7':
                target_positions = 7
            else:
                continue
                
            # Get current category data
            cat_df = df[cat_mask].copy()
            cat_df['Percentage'] = pd.to_numeric(cat_df['Percentage'], errors='coerce')
            cat_df = cat_df.sort_values('Percentage', ascending=False).reset_index(drop=True)
            
            # Find required brands and boost them to required positions
            for i, brand in enumerate(required_brands[:target_positions]):
                # Find brand (case insensitive)
                brand_mask = cat_df['Value'].str.contains(brand, case=False, na=False)
                if not brand_mask.any():
                    print(f"  ⚠️ Brand '{brand}' not found in {category}")
                    continue
                    
                brand_idx_in_cat = brand_mask.idxmax()
                current_position = brand_idx_in_cat + 1
                target_position = i + 1
                
                if current_position <= target_position:
                    print(f"  ✅ {brand} already in position {current_position} (target: {target_position})")
                    continue
                
                # Calculate boost value
                matching_cap = None
                for cap_brand, cap_range in individual_caps.items():
                    if brand.lower() == cap_brand.lower():
                        matching_cap = cap_range
                        break
                
                # Get the current top values to ensure we beat them
                current_top_values = cat_df['Percentage'].head(target_positions).values
                highest_current = current_top_values[0] if len(current_top_values) > 0 else 30
                
                if matching_cap:
                    min_val, max_val = matching_cap
                    # INDIVIDUAL CAPS TAKE ABSOLUTE PRECEDENCE - NEVER EXCEED THEM
                    # Use random value in upper portion of individual cap range
                    cap_range = max_val - min_val
                    # Use upper 30% of the cap range for positioning advantage
                    random_min = max_val - (cap_range * 0.3)
                    boost_value = np.random.uniform(random_min, max_val)
                    
                    # Ensure we NEVER exceed the individual cap maximum
                    boost_value = min(boost_value, max_val)
                else:
                    # No individual caps: use very high positioning value above current top
                    boost_value = highest_current + 10 - (i * 1) + np.random.uniform(-0.5, 0.5)
                
                # Ensure 4 decimal places
                boost_value = round(boost_value, 4)
                
                # Find the actual index in main dataframe
                df_mask = df['Column'].str.upper() == category.upper()
                brand_df_mask = df['Value'].str.contains(brand, case=False, na=False)
                df_idx = df[df_mask & brand_df_mask].index[0]
                
                old_value = df.at[df_idx, 'Percentage']
                df.at[df_idx, 'Percentage'] = boost_value
                print(f"  🚀 BOOSTED {brand}: {old_value:.2f}% → {boost_value:.2f}% (position {current_position} → target {target_position})")
        
        # Re-sort this category after positioning changes
        cat_indices = df[cat_mask].index
        if len(cat_indices) > 1:
            df.loc[cat_indices, 'Percentage'] = pd.to_numeric(df.loc[cat_indices, 'Percentage'], errors='coerce')
            cat_df_sorted = df.loc[cat_indices].sort_values('Percentage', ascending=False)
            df.loc[cat_indices] = cat_df_sorted.values
            print(f"  🔄 Re-sorted {category} after positioning enforcement")
    
    return df
def scale_raw_numbers_to_universe(df, universe_size):
    """
    Scale raw numbers proportionally to match the total unique users from universe scan.
    This preserves the actual underlying data relationships while scaling to the full universe.
    """
    if not SILENCE_VERBOSE_OUTPUT:
        print(f"\n📊 SCALING RAW NUMBERS TO UNIVERSE SIZE: {universe_size:,}")
        print("=" * 60)
    
    df = df.copy()
    
    # Get the current sample size from the SAMPLE SIZE row
    sample_size_mask = df['Column'].str.upper() == 'SAMPLE SIZE'
    if not sample_size_mask.any():
        if not SILENCE_VERBOSE_OUTPUT:
            print("⚠️ No SAMPLE SIZE row found, using universe size directly")
        current_sample_size = universe_size
    else:
        try:
            current_sample_size = int(float(str(df.loc[sample_size_mask, 'Percentage'].iloc[0]).replace(',', '')))
        except:
            current_sample_size = universe_size
    
    # Calculate base scaling factor
    if current_sample_size > 0:
        base_scale_factor = universe_size / current_sample_size
    else:
        base_scale_factor = 1.0
    
    # Add realistic jitter to avoid clean whole numbers (e.g., 100x becomes 97x, 101x, 103x)
    # Jitter range: ±3% variation for more realistic scaling
    jitter = np.random.uniform(0.97, 1.03)  # 97% to 103% variation
    scale_factor = base_scale_factor * jitter
    
    if not SILENCE_VERBOSE_OUTPUT:
        print(f"📊 Current sample size: {current_sample_size:,}")
        print(f"📊 Target universe size: {universe_size:,}")
        print(f"📊 Base scaling factor: {base_scale_factor:.2f}x")
        print(f"📊 Jitter applied: {jitter:.3f}")
        print(f"📊 Final scaling factor: {scale_factor:.2f}x")
    
    # Scale all Original Raw Numbers proportionally
    for idx, row in df.iterrows():
        # Skip special categories that shouldn't be scaled
        if row['Column'].upper() in ['SAMPLE SIZE', 'AVID FAN', 'CASUAL FAN', 'BRAND INPUT', 'INPUT_METADATA']:
            continue
            
        # Get current raw number
        current_raw = row.get('Original Raw Numbers', 0)
        if current_raw and str(current_raw) not in ['', 'nan', 'NaN', 'None']:
            try:
                # Convert to numeric and scale
                raw_numeric = float(str(current_raw).replace(',', ''))
                scaled_raw = raw_numeric * scale_factor
                
                # Add individual jitter to each raw number (±2% variation)
                individual_jitter = np.random.uniform(0.98, 1.02)  # 98% to 102% variation
                final_raw = int(scaled_raw * individual_jitter)
                
                # Ensure minimum of 1 for any non-zero original value
                if raw_numeric > 0:
                    final_raw = max(1, final_raw)
                
                df.loc[idx, 'Original Raw Numbers'] = final_raw
            except:
                # If conversion fails, keep original
                pass
    
    # Update the SAMPLE SIZE row to show the universe size
    if sample_size_mask.any():
        df.loc[sample_size_mask, 'Percentage'] = float(universe_size)
        # Update the Value field to show the date range
        sample_value = df.loc[sample_size_mask, 'Value'].iloc[0]
        if 'SAMPLE_START' in str(sample_value):
            # Keep the existing date format
            pass
        else:
            # Create new format if needed
            df.loc[sample_size_mask, 'Value'] = f"SAMPLE SIZE (UNIVERSE SCAN) | BEHAVIOR STUDY"
    
    if not SILENCE_VERBOSE_OUTPUT:
        print("✅ Raw numbers scaled to match universe size - preserving actual data relationships")
    
    return df

def fix_demographics_sum_to_sample_size(df):
    """
    Fix demographics so that each category's Original Raw Numbers sum to the sample size.
    This ensures demographic data is properly normalized.
    """
    if not SILENCE_VERBOSE_OUTPUT:
        print("\n📊 FIXING DEMOGRAPHICS TO SUM TO SAMPLE SIZE")
        print("=" * 50)
    
    df = df.copy()
    
    # Get sample size from SAMPLE SIZE row
    sample_size_mask = df['Column'].str.upper() == 'SAMPLE SIZE'
    if not sample_size_mask.any():
        if not SILENCE_VERBOSE_OUTPUT:
            print("⚠️ No SAMPLE SIZE row found")
        return df
    
    try:
        sample_size = int(float(str(df.loc[sample_size_mask, 'Percentage'].iloc[0]).replace(',', '')))
    except:
        if not SILENCE_VERBOSE_OUTPUT:
            print("⚠️ Could not parse sample size")
        return df
    
    # Demographic categories that should sum to sample size
    demographic_categories = ['AGE', 'GENDER', 'ETHNICITY', 'INCOME', 'EDUCATION', 'RELATIONSHIP', 'SEXUAL_ORIENTATION', 'PARENTAL_STATUS', 'OCCUPATION']
    
    for category in demographic_categories:
        cat_mask = df['Column'] == category
        if not cat_mask.any():
            continue
            
        cat_indices = df[cat_mask].index
        if len(cat_indices) == 0:
            continue
        
        # Get current raw numbers for this category
        current_raw_numbers = []
        for idx in cat_indices:
            raw_val = df.loc[idx, 'Original Raw Numbers']
            try:
                raw_num = float(str(raw_val).replace(',', ''))
                current_raw_numbers.append(raw_num)
            except:
                current_raw_numbers.append(0.0)
        
        # Calculate current sum
        current_sum = sum(current_raw_numbers)
        
        if current_sum > 0:
            # Calculate scaling factor to make sum equal to sample size
            scale_factor = sample_size / current_sum
            
            # Apply scaling to each raw number
            for i, idx in enumerate(cat_indices):
                scaled_raw = int(current_raw_numbers[i] * scale_factor)
                df.loc[idx, 'Original Raw Numbers'] = scaled_raw
            
            if not SILENCE_VERBOSE_OUTPUT:
                print(f"  📊 {category}: {current_sum:,.0f} → {sample_size:,} (scale: {scale_factor:.3f}x)")
    
    if not SILENCE_VERBOSE_OUTPUT:
        print("✅ Demographics fixed to sum to sample size")
    
    return df

def recalculate_percentages_from_raw_numbers(df):
    """
    Recalculate all percentages based on Original Raw Numbers to ensure directional alignment.
    This ensures that percentages are always calculated from the final raw numbers.
    """
    if not SILENCE_VERBOSE_OUTPUT:
        print("\n🔄 RECALCULATING PERCENTAGES FROM ORIGINAL RAW NUMBERS")
        print("=" * 60)
    
    df = df.copy()
    
    # Get all unique categories
    categories = df['Column'].unique()
    
    for category in categories:
        cat_mask = df['Column'] == category
        cat_indices = df[cat_mask].index
        
        if len(cat_indices) <= 1:
            continue
            
        # Use the correct column name that exists at this point in the pipeline
        raw_col = 'Original Raw Numbers (Database)' if 'Original Raw Numbers (Database)' in df.columns else 'Original Raw Numbers'
        
        # Convert Original Raw Numbers to numeric
        df.loc[cat_indices, raw_col] = pd.to_numeric(df.loc[cat_indices, raw_col], errors='coerce')
        
        # Calculate total raw numbers for this category
        total_raw = df.loc[cat_indices, raw_col].sum()
        
        if total_raw > 0:
            # Recalculate percentages based on raw numbers
            # Ensure values are numeric before calculation and rounding
            raw_values = pd.to_numeric(df.loc[cat_indices, raw_col], errors='coerce')
            percentages = (raw_values / total_raw * 100.0).round(4)
            df.loc[cat_indices, 'Percentage'] = percentages
            
            if not SILENCE_VERBOSE_OUTPUT:
                print(f"  📊 {category}: Recalculated {len(cat_indices)} entries from raw numbers")
        else:
            if not SILENCE_VERBOSE_OUTPUT:
                print(f"  ⚠️ {category}: No valid raw numbers found, keeping existing percentages")
    
    return df

def filter_invalid_dmas(df):
    """
    Filter out LOCATION entries that don't match the official 210 DMA list from GENPOP_DMA_PERCENTAGES.
    This removes "short" DMA names like "Augusta GA" when we should only have "Augusta Ga Aiken Sc".
    Uses the GenPop list as the canonical source since it has exactly 210 standard US DMAs.
    """
    if not SILENCE_VERBOSE_OUTPUT:
        print("\n🔍 FILTERING INVALID DMAs AGAINST 210 CANONICAL DMAs")
        print("=" * 40)

    location_mask = df['Column'].str.upper() == 'LOCATION'
    if not location_mask.any():
        return df

    location_df = df[location_mask].copy()
    other_df = df[~location_mask].copy()
    
    # Build canonical DMA lookup from GENPOP_DMA_PERCENTAGES (the authoritative 210 DMA list)
    canonical_dmas = {}  # key -> canonical display name
    for dma_name, _ in GENPOP_DMA_PERCENTAGES:
        key = dma_match_key(dma_name)
        canonical_dmas[key] = dma_name
    
    # Also build word-set lookup for fuzzy matching
    canonical_word_sets = {}
    for dma_name, _ in GENPOP_DMA_PERCENTAGES:
        key = dma_match_key(dma_name)
        words = frozenset(key.split())
        canonical_word_sets[words] = dma_name
    
    # Track which entries to keep (and optionally rename to canonical form)
    valid_entries = []
    removed_entries = []
    
    for idx, row in location_df.iterrows():
        dma_value = str(row['Value']).strip()
        dma_key = dma_match_key(dma_value)
        dma_words = frozenset(dma_key.split())
        
        matched_canonical = None
        
        # 1. Exact key match
        if dma_key in canonical_dmas:
            matched_canonical = canonical_dmas[dma_key]
        
        # 2. Word set match (handles reordering like "Augusta Aiken SC GA" vs "Augusta Ga Aiken Sc")
        elif dma_words in canonical_word_sets:
            matched_canonical = canonical_word_sets[dma_words]
        
        # 3. Check if this is a SHORT version of a canonical DMA
        # e.g., "Augusta GA" should NOT match "Augusta Ga Aiken Sc" - it's a subset
        # We ONLY accept if ALL words in canonical are present in input
        else:
            for canonical_words, canonical_name in canonical_word_sets.items():
                # If input words are a SUPERSET of canonical (has extra words), might be OK
                # If input words are a SUBSET of canonical (missing words), it's the short version - REJECT
                if dma_words.issubset(canonical_words) and dma_words != canonical_words:
                    # This is a short version - DON'T match it
                    continue
                elif dma_words.issuperset(canonical_words) and len(dma_words - canonical_words) <= 1:
                    # Input has 1 extra word but contains all canonical words - accept
                    matched_canonical = canonical_name
                    break
        
        if matched_canonical:
            # Keep the entry (optionally use canonical name for consistency)
            row_copy = row.copy()
            # Normalize to canonical display format
            row_copy['Value'] = normalize_dma_for_display(matched_canonical)
            valid_entries.append(row_copy)
        else:
            removed_entries.append(dma_value)
    
    if not SILENCE_VERBOSE_OUTPUT:
        print(f"  📊 Valid DMAs: {len(valid_entries)} / {len(location_df)}")
        if removed_entries:
            print(f"  🚫 Removed {len(removed_entries)} invalid/short DMAs:")
            for dma in sorted(set(removed_entries))[:15]:  # Show first 15 unique
                print(f"      - {dma}")
            if len(set(removed_entries)) > 15:
                print(f"      ... and {len(set(removed_entries)) - 15} more unique invalid DMAs")
    
    # Rebuild location dataframe with only valid entries
    if valid_entries:
        valid_location_df = pd.DataFrame(valid_entries)
        result_df = pd.concat([other_df, valid_location_df], ignore_index=True)
    else:
        result_df = other_df
    
    return result_df


def deduplicate_location_data(df):
    """
    Remove duplicate entries in the LOCATION category.
    Keep the entry with the highest percentage for each unique location.
    """
    if not SILENCE_VERBOSE_OUTPUT:
        print("\n🔍 DEDUPLICATING LOCATION DATA")
        print("=" * 40)

    location_mask = df['Column'].str.upper() == 'LOCATION'
    if not location_mask.any():
        return df

    location_df = df[location_mask].copy()
    other_df = df[~location_mask].copy()

    # Convert percentages to float for proper sorting
    location_df['Percentage'] = pd.to_numeric(location_df['Percentage'], errors='coerce')

    # Normalize display names and group case-insensitively
    location_df['Value'] = location_df['Value'].apply(normalize_dma_for_display)
    location_df['_match_key'] = location_df['Value'].apply(dma_match_key)
    location_deduplicated = location_df.sort_values('Percentage', ascending=False).drop_duplicates(subset='_match_key', keep='first')
    if '_match_key' in location_deduplicated.columns:
        location_deduplicated = location_deduplicated.drop(columns=['_match_key'])

    # Count duplicates removed
    original_count = len(location_df)
    deduplicated_count = len(location_deduplicated)
    duplicates_removed = original_count - deduplicated_count

    if not SILENCE_VERBOSE_OUTPUT:
        print(f"  📊 LOCATION entries: {original_count} → {deduplicated_count} (removed {duplicates_removed} duplicates)")

    # Recombine with other data
    result_df = pd.concat([other_df, location_deduplicated], ignore_index=True)

    return result_df

def enforce_exact_210_dmas(df):
    """
    Final hard gate for LOCATION:
    - Only canonical DMAs from ALLOWED_DMAS are permitted
    - Exactly 210 LOCATION rows are output
    - Percentages are renormalized to 100 with 4 decimals
    """
    import pandas as pd
    import numpy as np

    if 'Column' not in df.columns or 'Value' not in df.columns:
        return df

    bp_col = 'Brand Penetration (Row)' if 'Brand Penetration (Row)' in df.columns else None
    cs_col = 'Category Share' if 'Category Share' in df.columns else 'Percentage'
    pct_col = 'Percentage' if 'Percentage' in df.columns else cs_col
    raw_col = 'Original Raw Numbers' if 'Original Raw Numbers' in df.columns else None
    proj_col = 'US Gen Pop Projection' if 'US Gen Pop Projection' in df.columns else None
    MULT = 329_900_000 / 10_000_000

    def _to_num(v):
        try:
            return float(str(v).replace(',', '').replace('%', ''))
        except Exception:
            return 0.0

    out = df.copy()
    loc_mask = out['Column'].astype(str).str.upper().str.strip() == 'LOCATION'
    if not loc_mask.any():
        return out

    # Build canonical DMA map from the authoritative 210 DMA source.
    # Use GENPOP_DMA_PERCENTAGES names first; fallback to ALLOWED_DMAS.
    canonical_dma_names = []
    xlsx_dmas = _load_official_dma_names_from_xlsx(OFFICIAL_DMA_XLSX_PATH)
    if xlsx_dmas:
        canonical_dma_names = [normalize_dma_for_display(x) for x in xlsx_dmas]
        if not SILENCE_VERBOSE_OUTPUT:
            print(f"📍 Using official DMA xlsx list: {len(canonical_dma_names)} rows")
    try:
        if not canonical_dma_names:
            canonical_dma_names = [normalize_dma_for_display(str(name)) for name, _ in GENPOP_DMA_PERCENTAGES]
    except Exception:
        if not canonical_dma_names:
            canonical_dma_names = []
    if not canonical_dma_names:
        canonical_dma_names = [normalize_dma_for_display(x) for x in ALLOWED_DMAS]

    # Deduplicate while preserving order
    seen = set()
    canonical_dma_names = [d for d in canonical_dma_names if not (d in seen or seen.add(d))]

    # Build normalized match map
    canonical_map = {}
    for dma in canonical_dma_names:
        canonical_map[dma_match_key(dma)] = dma

    loc_df = out[loc_mask].copy()
    other_df = out[~loc_mask].copy()

    # Keep only rows that map to a canonical DMA key
    grouped = {}
    for _, row in loc_df.iterrows():
        key = dma_match_key(str(row.get('Value', '')))
        if key not in canonical_map:
            continue
        canon = canonical_map[key]
        grouped.setdefault(canon, 0.0)
        grouped[canon] += _to_num(row.get(cs_col, row.get(pct_col, 0)))

    # Ensure all canonical DMAs exist (expected 210)
    for canon in canonical_dma_names:
        grouped.setdefault(canon, 0.01)

    # Rebuild LOCATION frame with exactly 210 rows
    vals = pd.Series(grouped, dtype=float)
    vals[vals < 0.01] = 0.01
    vals = vals / float(vals.sum()) * 100.0
    vals = vals.round(4)

    # ── Population-aware hard clamp ──────────────────────────────────────
    # Regardless of what upstream agents produced, no DMA's final share can
    # deviate from its Gen Pop baseline by more than a sane multiplier.
    # This catches label-value mismatches, LLM hallucinations, and name-
    # matching bugs that bypass earlier guardrails.
    _gp_baseline_map = {}
    try:
        for _gn, _gp in GENPOP_DMA_PERCENTAGES:
            _gp_baseline_map[normalize_dma_for_display(str(_gn))] = float(_gp)
    except Exception:
        pass
    if _gp_baseline_map:
        _clamp_fixes = 0
        for dma_name in vals.index:
            baseline = _gp_baseline_map.get(dma_name)
            if baseline is None or baseline <= 0:
                continue
            current = float(vals[dma_name])
            implied_mult = current / baseline
            demo = DMA_DEMOGRAPHICS.get(dma_name.upper(), {})
            rank = demo.get("pop_rank", 999)
            if rank <= 30:
                clamped = max(0.3, min(5.0, implied_mult))
            elif rank <= 100:
                clamped = max(0.15, min(3.5, implied_mult))
            elif rank <= 150:
                clamped = max(0.1, min(2.5, implied_mult))
            else:
                clamped = max(0.1, min(2.0, implied_mult))
            if abs(clamped - implied_mult) > 0.01:
                vals[dma_name] = round(baseline * clamped, 4)
                _clamp_fixes += 1
        if _clamp_fixes:
            vals = vals / float(vals.sum()) * 100.0
            vals = vals.round(4)
            print(f"   🔒 Population-aware DMA clamp: corrected {_clamp_fixes} DMAs "
                  f"(top-30 floor=0.3x/ceil=5x, small-DMA ceil=2x)")

    drift = round(100.0 - float(vals.sum()), 4)
    if abs(drift) > 0:
        mx = vals.idxmax()
        vals[mx] = round(float(vals[mx]) + drift, 4)

    # Organic LOCATION de-templating:
    # 1) jitter all DMAs with small deterministic row-specific noise
    # 2) break exact duplicate values
    # 3) reduce repeated 4-digit suffix clusters (e.g., many *.0001 / *.9999)
    # while preserving exactly 100.0000 total via anchor compensation.
    base_vals = {name: round(float(v), 4) for name, v in vals.items()}
    working = dict(base_vals)

    # 1) Small deterministic jitter for every DMA (prevents rigid decimal patterns).
    total_delta = 0.0
    for dma_name in sorted(working.keys()):
        old = round(working[dma_name], 4)
        if old <= 0:
            continue
        # 0.0001..0.0049, deterministic per DMA
        mag = ((abs(hash(f"loc-organic-mag|{dma_name}")) % 49) + 1) / 10000.0
        sign = 1.0 if (abs(hash(f"loc-organic-sign|{dma_name}")) % 2) else -1.0
        if old <= mag + 0.0001:
            sign = 1.0
        new = round(max(0.0001, min(99.9999, old + sign * mag)), 4)
        working[dma_name] = new
        total_delta = round(total_delta + (new - old), 4)

    # Compensation anchor: largest DMA after jitter.
    anchor_name = max(working.keys(), key=lambda n: working[n])
    working[anchor_name] = round(max(0.0001, working[anchor_name] - total_delta), 4)

    # 2) Break exact duplicate 4dp values.
    compensation = 0.0
    dup_map = {}
    for n, v in working.items():
        dup_map.setdefault(round(v, 4), []).append(n)
    for _v, names in dup_map.items():
        names = sorted(names)
        if len(names) <= 1:
            continue
        for pos, dma_name in enumerate(names[1:], start=1):
            old = round(working[dma_name], 4)
            delta = ((abs(hash(f"loc-dedup|{dma_name}|{pos}")) % 71) + 1) / 10000.0
            sign = 1.0 if (abs(hash(f"loc-dedup-sign|{dma_name}|{pos}")) % 2) else -1.0
            if old <= delta + 0.0001:
                sign = 1.0
            new = round(max(0.0001, min(99.9999, old + sign * delta)), 4)
            if new == old:
                new = round(min(99.9999, old + 0.0001), 4)
            working[dma_name] = new
            compensation = round(compensation + (new - old), 4)

    if abs(compensation) > 0:
        working[anchor_name] = round(max(0.0001, working[anchor_name] - compensation), 4)

    # 3) Reduce repeated decimal suffixes by making suffixes unique where needed.
    suffix_owner = {}
    suffix_comp = 0.0
    for dma_name in sorted(working.keys(), key=lambda n: (-working[n], n)):
        old = round(working[dma_name], 4)
        s_old = f"{old:.4f}".split('.')[-1]
        if s_old not in suffix_owner:
            suffix_owner[s_old] = dma_name
            continue
        placed = False
        for attempt in range(1, 80):
            delta = ((abs(hash(f"loc-suffix|{dma_name}|{attempt}")) % 97) + 1) / 10000.0
            sign = 1.0 if (abs(hash(f"loc-suffix-sign|{dma_name}|{attempt}")) % 2) else -1.0
            if old <= delta + 0.0001:
                sign = 1.0
            cand = round(max(0.0001, min(99.9999, old + sign * delta)), 4)
            s_cand = f"{cand:.4f}".split('.')[-1]
            if s_cand not in suffix_owner:
                working[dma_name] = cand
                suffix_owner[s_cand] = dma_name
                suffix_comp = round(suffix_comp + (cand - old), 4)
                placed = True
                break
        if not placed:
            suffix_owner[s_old] = dma_name

    if abs(suffix_comp) > 0:
        working[anchor_name] = round(max(0.0001, working[anchor_name] - suffix_comp), 4)

    vals = pd.Series(working, dtype=float).round(4)
    drift = round(100.0 - float(vals.sum()), 4)
    if abs(drift) > 0:
        mx = vals.idxmax()
        vals[mx] = round(float(vals[mx]) + drift, 4)

    # Sample size for raw/projection recalc
    sample_size = 132040
    if raw_col:
        ss_mask = other_df['Column'].astype(str).str.upper().str.strip() == 'SAMPLE SIZE'
        if ss_mask.any():
            try:
                sample_size = max(1, int(float(str(other_df.loc[ss_mask, raw_col].iloc[0]).replace(',', ''))))
            except Exception:
                pass

    loc_rows = []
    for dma_name, pct in vals.items():
        row = {'Column': 'LOCATION', 'Value': dma_name}
        if bp_col:
            row[bp_col] = f"{float(pct):.4f}"
        if cs_col:
            row[cs_col] = f"{float(pct):.4f}"
        if pct_col:
            row[pct_col] = f"{float(pct):.4f}"
        if raw_col:
            raw_num = max(1, int(round(float(pct) / 100.0 * sample_size)))
            row[raw_col] = str(raw_num)
            if proj_col:
                row[proj_col] = str(int(round(raw_num * MULT)))
        loc_rows.append(row)

    new_loc_df = pd.DataFrame(loc_rows)
    result = pd.concat([other_df, new_loc_df], ignore_index=True)
    if not SILENCE_VERBOSE_OUTPUT:
        print(f"📍 Final LOCATION canonicalization: {len(new_loc_df)} DMAs (expected 210)")
    return result

def enforce_black_audience_dma_guard(df):
    """
    Deterministic post-AI LOCATION guard:
    if ETHNICITY indicates a clearly Black-skewing audience, enforce minimum
    floors for core Black-audience DMAs (e.g., DC, Atlanta, Houston, Detroit).
    Then renormalize LOCATION back to exactly 100%.
    """
    import pandas as pd

    if 'Column' not in df.columns or 'Value' not in df.columns:
        return df

    bp_col = 'Brand Penetration (Row)' if 'Brand Penetration (Row)' in df.columns else None
    cs_col = 'Category Share' if 'Category Share' in df.columns else 'Percentage'
    pct_col = 'Percentage' if 'Percentage' in df.columns else cs_col
    raw_col = 'Original Raw Numbers' if 'Original Raw Numbers' in df.columns else None
    proj_col = 'US Gen Pop Projection' if 'US Gen Pop Projection' in df.columns else None
    MULT = 329_900_000 / 10_000_000

    def _to_num(v):
        try:
            return float(str(v).replace(',', '').replace('%', ''))
        except Exception:
            return 0.0

    out = df.copy()

    # Detect Black-audience skew from ETHNICITY rows.
    eth_mask = out['Column'].astype(str).str.upper().str.strip() == 'ETHNICITY'
    if not eth_mask.any():
        return out

    black_pct = 0.0
    for _, row in out[eth_mask].iterrows():
        v = str(row.get('Value', '')).strip().upper()
        if 'BLACK' in v and 'AFRICAN' in v:
            black_pct += _to_num(row.get(cs_col, row.get(pct_col, 0)))

    # Trigger only for clearly Black-skewing audiences.
    if black_pct < 16.0:
        return out

    loc_mask = out['Column'].astype(str).str.upper().str.strip() == 'LOCATION'
    if not loc_mask.any():
        return out

    loc_idx = list(out[loc_mask].index)
    if not loc_idx:
        return out

    # Build LOCATION table.
    loc_vals = {}
    loc_names = {}
    for i in loc_idx:
        name = str(out.at[i, 'Value']).strip()
        loc_names[i] = name
        loc_vals[i] = max(0.01, _to_num(out.at[i, cs_col] if cs_col in out.columns else out.at[i, pct_col]))

    # Match DMA rows using robust keyword matching against canonical names.
    def _find_dma_idx(required_words):
        candidates = []
        req = [w.lower() for w in required_words]
        for i in loc_idx:
            key = dma_match_key(loc_names.get(i, ''))
            if all(w in key for w in req):
                candidates.append(i)
        if not candidates:
            return None
        return max(candidates, key=lambda x: loc_vals.get(x, 0.0))

    # Dynamic floors based on Black share. Tuned to be directional, not extreme.
    signal = max(0.0, black_pct - 12.0)
    floor_map = {
        ('WASHINGTON', 'DC'): min(4.5, 1.2 + 0.06 * signal),
        ('ATLANTA',): min(5.5, 1.6 + 0.08 * signal),
        ('HOUSTON',): min(4.0, 1.2 + 0.06 * signal),
        ('DETROIT',): min(3.5, 0.9 + 0.05 * signal),
        ('MEMPHIS',): min(2.0, 0.45 + 0.03 * signal),
        ('NEW', 'ORLEANS'): min(2.0, 0.45 + 0.03 * signal),
        ('BALTIMORE',): min(2.8, 0.7 + 0.04 * signal),
    }

    # Lift floors to at least modest over-index vs GenPop for matching DMAs.
    gp_dma = {str(name).upper(): float(pct) for name, pct in GENPOP_DMA_PERCENTAGES}
    targets = []
    for words, floor in floor_map.items():
        idx = _find_dma_idx(words)
        if idx is None:
            continue
        dma_name = str(loc_names[idx]).upper()
        gp_pct = gp_dma.get(dma_name, 0.0)
        floor = max(floor, gp_pct * 1.15)
        targets.append((idx, floor))

    if not targets:
        return out

    changed = 0
    for idx, floor in targets:
        cur = loc_vals[idx]
        if cur + 1e-9 < floor:
            loc_vals[idx] = floor
            changed += 1

    if changed == 0:
        return out

    # Renormalize back to 100 while preserving minimum 0.01 everywhere.
    total = sum(loc_vals.values())
    if total <= 0:
        return out

    excess = total - 100.0
    if excess > 0:
        target_idx = {i for i, _ in targets}
        reducible = [i for i in loc_idx if i not in target_idx and loc_vals[i] > 0.01]
        available = sum(max(0.0, loc_vals[i] - 0.01) for i in reducible)
        if available > 0:
            take = min(excess, available)
            for i in reducible:
                headroom = max(0.0, loc_vals[i] - 0.01)
                if headroom <= 0:
                    continue
                delta = take * (headroom / available)
                loc_vals[i] = max(0.01, loc_vals[i] - delta)
        else:
            scale = 100.0 / total
            for i in loc_idx:
                loc_vals[i] = max(0.01, loc_vals[i] * scale)

    # Final exact normalization + 4-decimal drift correction.
    vals = pd.Series({i: loc_vals[i] for i in loc_idx}, dtype=float)
    vals[vals < 0.01] = 0.01
    vals = vals / float(vals.sum()) * 100.0
    vals = vals.round(4)
    drift = round(100.0 - float(vals.sum()), 4)
    if abs(drift) > 0:
        mx = vals.idxmax()
        vals[mx] = round(float(vals[mx]) + drift, 4)

    # Recompute raw/projection from SAMPLE SIZE.
    sample_size = 132040
    if raw_col:
        ss_mask = out['Column'].astype(str).str.upper().str.strip() == 'SAMPLE SIZE'
        if ss_mask.any():
            try:
                sample_size = max(1, int(float(str(out.loc[ss_mask, raw_col].iloc[0]).replace(',', ''))))
            except Exception:
                pass

    for i in loc_idx:
        pct = float(vals[i])
        if bp_col:
            out.at[i, bp_col] = f"{pct:.4f}"
        if cs_col:
            out.at[i, cs_col] = f"{pct:.4f}"
        if pct_col:
            out.at[i, pct_col] = f"{pct:.4f}"
        if raw_col:
            raw_num = max(1, int(round(pct / 100.0 * sample_size)))
            out.at[i, raw_col] = str(raw_num)
            if proj_col:
                out.at[i, proj_col] = str(int(round(raw_num * MULT)))

    if not SILENCE_VERBOSE_OUTPUT:
        print(f"📍 Black-audience DMA guard: Black={black_pct:.2f}% — enforced {changed} DMA floor(s)")

    return out


def enforce_no_age_other_and_rebase(df):
    """
    Hard AGE guard:
    - Remove any AGE row where Value is "OTHER" (or starts with OTHER / ANOTHER).
    - Renormalize AGE to exactly 100.0000 using BP as source of truth.
    """
    import pandas as pd

    if 'Column' not in df.columns or 'Value' not in df.columns:
        return df

    out = df.copy()
    age_mask = out['Column'].astype(str).str.upper().str.strip() == 'AGE'
    if not age_mask.any():
        return out

    bp_col = 'Brand Penetration (Row)' if 'Brand Penetration (Row)' in out.columns else None
    cs_col = 'Category Share' if 'Category Share' in out.columns else None
    pct_col = 'Percentage' if 'Percentage' in out.columns else None
    raw_col = 'Original Raw Numbers' if 'Original Raw Numbers' in out.columns else None
    proj_col = 'US Gen Pop Projection' if 'US Gen Pop Projection' in out.columns else None
    MULT = 329_900_000 / 10_000_000

    def _to_num(v):
        try:
            return float(str(v).replace(',', '').replace('%', '').strip())
        except Exception:
            return 0.0

    def _is_other_age(v):
        s = str(v).strip().upper()
        return s == 'OTHER' or s.startswith('OTHER ') or s.startswith('ANOTHER')

    age_df = out[age_mask].copy()
    drop_idx = [i for i in age_df.index if _is_other_age(age_df.at[i, 'Value'])]
    removed = len(drop_idx)
    if removed == 0:
        return out

    keep_age = age_df.drop(index=drop_idx)
    if keep_age.empty:
        return out

    source_col = bp_col or cs_col or pct_col
    if not source_col:
        out = out.drop(index=drop_idx).reset_index(drop=True)
        return out

    vals = keep_age[source_col].map(_to_num).astype(float)
    vals[vals < 0] = 0.0
    total = float(vals.sum())
    if total <= 0:
        vals[:] = 100.0 / len(vals)
    else:
        vals = (vals / total) * 100.0
    vals = vals.round(4)
    drift = round(100.0 - float(vals.sum()), 4)
    if abs(drift) > 0:
        mx = vals.idxmax()
        vals.loc[mx] = round(float(vals.loc[mx]) + drift, 4)

    for i in keep_age.index:
        s = f"{float(vals.loc[i]):.4f}"
        if bp_col:
            out.at[i, bp_col] = s
        if cs_col:
            out.at[i, cs_col] = s
        if pct_col:
            out.at[i, pct_col] = s

    sample_size = 132040
    if raw_col:
        ss_mask = out['Column'].astype(str).str.upper().str.strip() == 'SAMPLE SIZE'
        if ss_mask.any():
            try:
                sample_size = max(1, int(float(str(out.loc[ss_mask, raw_col].iloc[0]).replace(',', ''))))
            except Exception:
                pass
        for i in keep_age.index:
            bp = float(vals.loc[i])
            raw_num = max(1, int(round((bp / 100.0) * sample_size)))
            out.at[i, raw_col] = str(raw_num)
            if proj_col:
                out.at[i, proj_col] = str(int(round(raw_num * MULT)))

    out = out.drop(index=drop_idx).reset_index(drop=True)
    if not SILENCE_VERBOSE_OUTPUT:
        print(f"🧱 AGE guard: removed {removed} OTHER row(s), rebased AGE to 100.0000")
    return out


def enforce_behavioral_category_plausibility(df, brand_category=None, project_name=None, brands=None):
    """
    Deterministic post-AI behavioral guardrails for obvious US plausibility misses.
    These are intentionally narrow and only apply directional corrections.
    """
    import pandas as pd

    if 'Column' not in df.columns or 'Value' not in df.columns:
        return df

    out = df.copy()
    bp_col = 'Brand Penetration (Row)' if 'Brand Penetration (Row)' in out.columns else None
    if not bp_col:
        return out
    cs_col = 'Category Share' if 'Category Share' in out.columns else 'Percentage'
    pct_col = 'Percentage' if 'Percentage' in out.columns else cs_col
    raw_col = 'Original Raw Numbers' if 'Original Raw Numbers' in out.columns else None
    proj_col = 'US Gen Pop Projection' if 'US Gen Pop Projection' in out.columns else None
    MULT = 329_900_000 / 10_000_000

    def _to_num(v):
        try:
            return float(str(v).replace(',', '').replace('%', ''))
        except Exception:
            return 0.0

    # sample size for raw/projection refresh
    sample_size = 132040
    if raw_col:
        ss_mask = out['Column'].astype(str).str.upper().str.strip() == 'SAMPLE SIZE'
        if ss_mask.any():
            try:
                sample_size = max(1, int(float(str(out.loc[ss_mask, raw_col].iloc[0]).replace(',', ''))))
            except Exception:
                pass

    # demographic skew controls (only for context-sensitive rules)
    male_pct = 0.0
    young_pct = 0.0
    black_pct = 0.0
    gmask = out['Column'].astype(str).str.upper().str.strip() == 'GENDER'
    for _, row in out[gmask].iterrows():
        val = str(row.get('Value', '')).strip().upper()
        p = _to_num(row.get(cs_col, row.get(pct_col, 0)))
        if val in ('MALE', 'TRANS MALE'):
            male_pct += p
    amask = out['Column'].astype(str).str.upper().str.strip() == 'AGE'
    for _, row in out[amask].iterrows():
        val = str(row.get('Value', '')).strip().upper()
        p = _to_num(row.get(cs_col, row.get(pct_col, 0)))
        if any(x in val for x in ['18-24', '25-34', '18 -', '25 -', 'GEN Z', 'MILLENNIAL']):
            young_pct += p
    emask = out['Column'].astype(str).str.upper().str.strip() == 'ETHNICITY'
    for _, row in out[emask].iterrows():
        val = str(row.get('Value', '')).strip().upper()
        p = _to_num(row.get(cs_col, row.get(pct_col, 0)))
        if 'BLACK' in val and 'AFRICAN' in val:
            black_pct += p

    def _cat_rows(cat):
        m = out['Column'].astype(str).str.upper().str.strip() == str(cat).upper()
        rows = []
        for idx, row in out[m].iterrows():
            rows.append((idx, str(row.get('Value', '')).strip(), _to_num(row.get(bp_col, 0))))
        return rows

    def _find_idx(cat, needle_list):
        rows = _cat_rows(cat)
        for n in needle_list:
            n_up = str(n).upper()
            for idx, val, _bp in rows:
                if n_up in str(val).upper():
                    return idx
        return None

    def _bp(idx):
        return _to_num(out.at[idx, bp_col])

    def _write_bp(idx, new_bp):
        new_bp = max(0.01, min(float(new_bp), 95.0))
        s = f"{new_bp:.4f}"
        out.at[idx, bp_col] = s
        if cs_col in out.columns:
            out.at[idx, cs_col] = s
        if pct_col in out.columns:
            out.at[idx, pct_col] = s
        if raw_col:
            raw = max(1, int(round(new_bp / 100.0 * sample_size)))
            out.at[idx, raw_col] = str(raw)
            if proj_col:
                out.at[idx, proj_col] = str(int(round(raw * MULT)))

    fixes = 0

    # 1) BETTING: DK/FD over Bet365 only for likely US sports-betting audience shape
    sports_betting_shape = (male_pct >= 52.0) or (young_pct >= 45.0) or (black_pct >= 25.0 and male_pct >= 45.0)
    if sports_betting_shape:
        bet365_idx = _find_idx('BETTING', ['BET365'])
        dk_idx = _find_idx('BETTING', ['DRAFTKINGS', 'DRAFT KINGS'])
        fd_idx = _find_idx('BETTING', ['FANDUEL', 'FAN DUEL'])
        if bet365_idx is not None and (dk_idx is not None or fd_idx is not None):
            b = _bp(bet365_idx)
            dk = _bp(dk_idx) if dk_idx is not None else None
            fd = _bp(fd_idx) if fd_idx is not None else None
            leader = max([x for x in [dk, fd] if x is not None] or [0.0])
            if b > leader and leader > 0:
                target_b = max(0.01, leader * 0.92)
                _write_bp(bet365_idx, target_b)
                fixes += 1
                b = target_b
            if dk_idx is not None and dk is not None and dk < b * 1.05:
                _write_bp(dk_idx, min(95.0, b * 1.08))
                fixes += 1
            if fd_idx is not None and fd is not None and fd < b * 1.05:
                _write_bp(fd_idx, min(95.0, b * 1.08))
                fixes += 1

    # 2) MEDIA: TODAY/TODAY SHOW should not dominate younger/male-skewing audiences
    if (male_pct >= 55.0 and young_pct >= 40.0) or (black_pct >= 25.0):
        today_idx = _find_idx('MEDIA', ['TODAY SHOW', 'THE TODAY SHOW', 'TODAY'])
        if today_idx is not None and _bp(today_idx) > 8.0:
            _write_bp(today_idx, 8.0)
            fixes += 1

    # 2b) MEDIA: For US audiences, BBC should not lead mainstream US publications.
    # Allow exceptions only when project/brand clearly signals UK/international focus.
    identity_blob = " ".join(
        [str(project_name or ""), str(brand_category or "")]
        + [str(b) for b in (brands or [])]
    ).upper()
    is_uk_context = any(tok in identity_blob for tok in [' UK ', ' BRIT', ' BRITISH', ' LONDON ', ' ENGLAND ', ' BBC'])
    if not is_uk_context:
        bbc_idx = _find_idx('MEDIA', ['BRITISH BROADCASTING CORPORATION', 'BBC'])
        if bbc_idx is not None:
            us_anchor_tokens = [
                'TODAY', 'YAHOO NEWS', 'USA TODAY', 'CNN', 'ABC NEWS', 'CBS NEWS',
                'FOX NEWS', 'GOOGLE NEWS', 'WASHINGTON POST', 'NEW YORK TIMES'
            ]
            anchor_idx = _find_idx('MEDIA', us_anchor_tokens)
            bbc_bp = _bp(bbc_idx)
            anchor_bp = _bp(anchor_idx) if anchor_idx is not None else 0.0
            # In US gen-pop based audiences, BBC can be present but should not dominate.
            target = max(12.0, min(18.5, (anchor_bp - 0.4) if anchor_bp > 0 else 18.5))
            if bbc_bp > target:
                _write_bp(bbc_idx, target)
                fixes += 1

    # 3) WHERE THEY DINE: if top item is unknown/niche and too high, cap it
    mainstream_dine_tokens = [
        'APPLEBEE', 'CHILI', 'BUFFALO WILD WINGS', 'OLIVE GARDEN', 'TEXAS ROADHOUSE',
        'CHEESECAKE FACTORY', 'LONGHORN', 'IHOP', 'RED LOBSTER', 'RED ROBIN',
        'OUTBACK', 'DAVE & BUSTER', 'TGI FRIDAYS'
    ]
    dine_rows = sorted(_cat_rows('WHERE THEY DINE'), key=lambda x: -x[2])
    if dine_rows:
        top_idx, top_val, top_bp = dine_rows[0]
        is_mainstream = any(tok in top_val.upper() for tok in mainstream_dine_tokens)
        if (not is_mainstream) and top_bp >= 8.0:
            _write_bp(top_idx, 3.5)
            fixes += 1

    # 4) QSR: Buffalo Wild Wings should not be buried for this audience shape
    if (male_pct >= 55.0 and young_pct >= 40.0) or (black_pct >= 25.0):
        bww_idx = _find_idx('QSR', ['BUFFALO WILD WINGS', 'BWW'])
        if bww_idx is not None and _bp(bww_idx) < 6.5:
            _write_bp(bww_idx, 7.5)
            fixes += 1

    # 5) WHERE THEY SHOP: small uplift for sports/shoe retail presence
    if (male_pct >= 55.0 and young_pct >= 40.0) or (black_pct >= 25.0):
        shop_rows = _cat_rows('WHERE THEY SHOP')
        sport_tokens = [
            'FOOT LOCKER', 'DICKS SPORTING', "DICK'S SPORTING", 'CHAMPS',
            'FINISH LINE', 'JD SPORTS', 'HIBBETT', 'SNIPES', 'NIKE', 'ADIDAS'
        ]
        for idx, val, cur in shop_rows:
            if any(tok in val.upper() for tok in sport_tokens):
                new_v = min(95.0, cur * 1.12)
                if abs(new_v - cur) >= 0.15:
                    _write_bp(idx, new_v)
                    fixes += 1

    if not SILENCE_VERBOSE_OUTPUT and fixes:
        print(f"🛡️ Behavioral plausibility guard: {fixes} deterministic correction(s)")

    return out

def enforce_behavioral_bp_uniqueness(df):
    """
    Reduce synthetic-looking repeated Brand Penetration values in behavioral
    categories by applying tiny deterministic jitter to ties.
    """
    import pandas as pd

    if 'Column' not in df.columns or 'Value' not in df.columns:
        return df

    out = df.copy()
    bp_col = 'Brand Penetration (Row)' if 'Brand Penetration (Row)' in out.columns else None
    if not bp_col:
        return out
    cs_col = 'Category Share' if 'Category Share' in out.columns else 'Percentage'
    pct_col = 'Percentage' if 'Percentage' in out.columns else cs_col
    raw_col = 'Original Raw Numbers' if 'Original Raw Numbers' in out.columns else None
    proj_col = 'US Gen Pop Projection' if 'US Gen Pop Projection' in out.columns else None
    MULT = 329_900_000 / 10_000_000

    demo_meta = {
        'AGE', 'GENDER', 'ETHNICITY', 'INCOME', 'EDUCATION', 'RELATIONSHIP',
        'SEXUAL_ORIENTATION', 'PARENTAL_STATUS', 'OCCUPATION', 'LOCATION',
        'INPUT_METADATA', 'BRAND INPUT', 'SAMPLE SIZE', 'AVID FAN', 'CASUAL FAN', 'BRAND CATEGORY'
    }

    def _to_num(v):
        try:
            return float(str(v).replace(',', '').replace('%', ''))
        except Exception:
            return 0.0

    sample_size = 132040
    if raw_col:
        ss_mask = out['Column'].astype(str).str.upper().str.strip() == 'SAMPLE SIZE'
        if ss_mask.any():
            try:
                sample_size = max(1, int(float(str(out.loc[ss_mask, raw_col].iloc[0]).replace(',', ''))))
            except Exception:
                pass

    touched = 0
    for cat in out['Column'].astype(str).str.upper().str.strip().unique():
        if cat in demo_meta:
            continue
        cm = out['Column'].astype(str).str.upper().str.strip() == cat
        sub = out[cm].copy()
        if sub.empty:
            continue
        sub['_bp'] = sub[bp_col].map(_to_num).round(4)
        dup_counts = sub['_bp'].value_counts()
        dup_vals = [v for v, c in dup_counts.items() if c > 1 and v >= 0.05]
        if not dup_vals:
            continue
        for dv in dup_vals:
            dup_idx = list(sub[sub['_bp'] == dv].index)
            for k, ridx in enumerate(dup_idx):
                # deterministic micro-jitter (~0.0001-0.0490) with alternating sign.
                # Wider spread avoids repeated 4-decimal ties across large groups.
                step = ((abs(hash(f"{cat}|{ridx}|{k}")) % 490) + 1) / 10000.0
                sign = -1.0 if (k % 2 == 0) else 1.0
                new_bp = max(0.01, min(95.0, dv + sign * step))
                s = f"{new_bp:.4f}"
                out.at[ridx, bp_col] = s
                if cs_col in out.columns:
                    out.at[ridx, cs_col] = s
                if pct_col in out.columns:
                    out.at[ridx, pct_col] = s
                if raw_col:
                    raw = max(1, int(round(new_bp / 100.0 * sample_size)))
                    out.at[ridx, raw_col] = str(raw)
                    if proj_col:
                        out.at[ridx, proj_col] = str(int(round(raw * MULT)))
                touched += 1

        # Second pass: de-round suspiciously "perfect" values like 40.0004,
        # 25.0006, 60.0098 in behavioral categories.
        for ridx in sub.index:
            cur = _to_num(out.at[ridx, bp_col])
            if cur <= 0.01:
                continue
            frac = abs(cur - round(cur))
            near_integer = (frac < 0.02) or (frac > 0.98)
            # Also catch values that are effectively one-decimal/whole-number shapes.
            near_one_decimal = abs(cur - round(cur, 1)) < 0.01
            if not (near_integer or near_one_decimal):
                continue
            # Deterministic perturbation: 0.0830..0.3470
            mag = ((abs(hash(f"deround|{cat}|{ridx}")) % 265) + 83) / 1000.0
            sign = -1.0 if (abs(hash(f"sign|{cat}|{ridx}")) % 2 == 0) else 1.0
            new_bp = max(0.01, min(95.0, cur + sign * mag))
            # If this still lands near integer, nudge again.
            nfrac = abs(new_bp - round(new_bp))
            if nfrac < 0.01 or nfrac > 0.99:
                new_bp = max(0.01, min(95.0, new_bp + (0.137 if sign < 0 else -0.137)))
            s = f"{new_bp:.4f}"
            out.at[ridx, bp_col] = s
            if cs_col in out.columns:
                out.at[ridx, cs_col] = s
            if pct_col in out.columns:
                out.at[ridx, pct_col] = s
            if raw_col:
                raw = max(1, int(round(new_bp / 100.0 * sample_size)))
                out.at[ridx, raw_col] = str(raw)
                if proj_col:
                    out.at[ridx, proj_col] = str(int(round(raw * MULT)))
            touched += 1

    if not SILENCE_VERBOSE_OUTPUT and touched:
        print(f"🎛️ Behavioral BP uniqueness guard: jittered {touched} tied values")
    return out

def deduplicate_values_within_category(df):
    """
    Final safeguard: remove duplicate Value rows inside each Column category.
    Keeps one row per canonicalized value and sums percentages/counts.
    """
    import pandas as pd

    if 'Column' not in df.columns or 'Value' not in df.columns:
        return df

    bp_col = 'Brand Penetration (Row)' if 'Brand Penetration (Row)' in df.columns else None
    cs_col = 'Category Share' if 'Category Share' in df.columns else None
    pct_col = 'Percentage' if 'Percentage' in df.columns else None
    raw_col = 'Original Raw Numbers' if 'Original Raw Numbers' in df.columns else None
    proj_col = 'US Gen Pop Projection' if 'US Gen Pop Projection' in df.columns else None

    def _num(v):
        try:
            return float(str(v).replace(',', '').replace('%', ''))
        except Exception:
            return 0.0

    out = df.copy()
    out['_CAT_KEY'] = out['Column'].astype(str).str.strip().str.upper()
    out['_VAL_KEY'] = out.apply(
        lambda r: _canonical_demo_value(str(r['Column']), str(r['Value'])),
        axis=1
    )

    keep_rows = []
    for (cat_key, val_key), g in out.groupby(['_CAT_KEY', '_VAL_KEY'], dropna=False):
        row = g.iloc[0].copy()
        row['Column'] = cat_key
        row['Value'] = str(g.iloc[0]['Value']).strip()
        # Sum numeric-like metrics where present
        if bp_col:
            row[bp_col] = sum(_num(v) for v in g[bp_col].tolist())
        if cs_col:
            row[cs_col] = sum(_num(v) for v in g[cs_col].tolist())
        if pct_col and (cs_col is None or pct_col != cs_col):
            row[pct_col] = sum(_num(v) for v in g[pct_col].tolist())
        if raw_col:
            row[raw_col] = int(round(sum(_num(v) for v in g[raw_col].tolist())))
        if proj_col:
            row[proj_col] = int(round(sum(_num(v) for v in g[proj_col].tolist())))
        keep_rows.append(row)

    result = pd.DataFrame(keep_rows).drop(columns=['_CAT_KEY', '_VAL_KEY'], errors='ignore')
    if not SILENCE_VERBOSE_OUTPUT:
        removed = len(df) - len(result)
        if removed > 0:
            print(f"🧹 Final category dedupe: removed {removed} duplicate rows")
    return result

