def add_original_raw_numbers_sorted_view(df):
    """
    Add a display-only column 'Original Raw Numbers (Sorted View)' that, within each
    category, contains the values of 'Original Raw Numbers (Database)' sorted
    descending. This does NOT change the original DB column and does not move rows.
    It is solely for presentation/export while preserving cross-category equality.
    
    Keeps demographic raw numbers unchanged; sorting logic is behavioral-only.
    """
    import pandas as pd

    db_col = 'Original Raw Numbers (Database)'
    src_col = 'Original Raw Numbers' if 'Original Raw Numbers' in df.columns else db_col
    view_col = 'Original Raw Numbers (Sorted View)'
    if src_col not in df.columns:
        return df

    # Initialize the view column with existing values (as strings)
    df[view_col] = df[src_col].astype(str)
    
    # Categories to skip for sorting (do not reshuffle row meaning)
    demographic_categories = {
        'GENDER', 'AGE', 'ETHNICITY', 'INCOME', 'EDUCATION', 'RELATIONSHIP',
        'SEXUAL_ORIENTATION', 'PARENTAL_STATUS', 'LOCATION', 'OCCUPATION',
        'SAMPLE SIZE', 'AVID FAN', 'CASUAL FAN', 'BRAND CATEGORY'
    }

    # For behavioral categories only, sort the numeric values descending
    for category in df['Column'].unique():
        if str(category).upper() in demographic_categories:
            continue  # Skip demographics
            
        mask = df['Column'] == category
        if not mask.any():
            continue
        series = df.loc[mask, src_col].astype(str)
        numeric_vals = pd.to_numeric(series.str.replace(',', ''), errors='coerce')

        numeric_idx = numeric_vals.dropna().index.tolist()
        if len(numeric_idx) == 0:
            continue

        sorted_numbers = sorted(numeric_vals.dropna().tolist(), reverse=True)
        for assign_pos, value in zip(numeric_idx, sorted_numbers):
            try:
                df.at[assign_pos, view_col] = str(int(round(value)))
            except Exception:
                df.at[assign_pos, view_col] = str(value)

    return df

def finalize_original_raw_numbers_for_output(df):
    """
    - Rename 'Original Raw Numbers (Sorted View)' -> 'Original Raw Numbers'
    - Drop 'Original Raw Numbers (Database)'
    - Ensure 'Original Raw Numbers' never equals sample size unless BRAND INPUT
    - Ensure all values are unique within each category by adding tiny noise if needed
    - Preserves demographic raw numbers computed earlier in the pipeline
    """
    import pandas as pd
    import numpy as np

    view_col = 'Original Raw Numbers (Sorted View)'
    final_col = 'Original Raw Numbers'
    db_col = 'Original Raw Numbers (Database)'

    # If the sorted view doesn't exist, nothing to finalize
    if view_col not in df.columns:
        return df

    # Drop existing final_col first to avoid duplicate column names after rename
    if final_col in df.columns and view_col in df.columns:
        df = df.drop(columns=[final_col])

    # Rename view -> final name
    df = df.rename(columns={view_col: final_col})

    # Drop DB column if present
    if db_col in df.columns:
        df = df.drop(columns=[db_col])

    # Resolve sample size from Original Raw Numbers or Category Share
    # (NOT Percentage, which holds the sampling rate e.g. 99.99%)
    sample_mask = df['Column'].str.upper() == 'SAMPLE SIZE'
    sample_size = None
    if sample_mask.any():
        for _ss_col in ['Original Raw Numbers', 'Category Share', 'Percentage']:
            if _ss_col not in df.columns:
                continue
            try:
                _ss_val = df.loc[sample_mask, _ss_col].iloc[0]
                _ss_candidate = int(float(str(_ss_val).replace(',', '')))
                if _ss_candidate > 1000:
                    sample_size = _ss_candidate
                    break
            except Exception:
                continue

    # Ensure final raw numbers are strings; store a numeric copy for ops
    df[final_col] = df[final_col].astype(str)

    # Identify BRAND INPUT brand(s) for exemption
    brand_input_mask = df['Column'].str.upper() == 'BRAND INPUT'
    brand_input_brands = set()
    if brand_input_mask.any():
        for _, r in df[brand_input_mask].iterrows():
            brand_input_brands.add(str(r.get('Value', '')).strip().upper())

    # Pass 1a: enforce cross-category equality for final raw numbers per brand (use highest)
    brand_max_raw = {}
    for _, r in df.iterrows():
        col = str(r.get('Column', '')).upper()
        if col in ['INPUT_METADATA', 'SAMPLE SIZE', 'PURCHASE SHARE', 'BRAND PENETRATION']:
            continue
        brand = str(r.get('Value', '')).strip().upper()
        try:
            raw_num = int(float(str(r.get(final_col, '')).replace(',', '')))
        except Exception:
            continue
        prev = brand_max_raw.get(brand)
        if prev is None or raw_num > prev:
            brand_max_raw[brand] = raw_num

    # Apply brand maxima and sample-size equality rule (non-input brands cannot equal sample size)
    if sample_size is not None:
        for brand in list(brand_max_raw.keys()):
            max_val = brand_max_raw[brand]
            if max_val == sample_size and brand not in brand_input_brands:
                brand_max_raw[brand] = sample_size - 1

    for idx, r in df.iterrows():
        col = str(r.get('Column', '')).upper()
        if col in ['INPUT_METADATA', 'SAMPLE SIZE', 'PURCHASE SHARE', 'BRAND PENETRATION']:
            continue
        brand = str(r.get('Value', '')).strip().upper()
        if brand in brand_max_raw:
            df.at[idx, final_col] = str(brand_max_raw[brand])

    # Pass 1b: prevent equals sample size unless BRAND INPUT (in case sample_size was None above)
    if sample_size is not None:
        for idx, row in df.iterrows():
            if str(row.get('Column', '')).upper() in ['INPUT_METADATA', 'SAMPLE SIZE', 'PURCHASE SHARE', 'BRAND PENETRATION']:
                continue
            brand_name = str(row.get('Value', '')).strip().upper()
            try:
                raw_num = int(float(str(row.get(final_col, '')).replace(',', '')))
            except Exception:
                continue
            if raw_num == sample_size and brand_name not in brand_input_brands:
                df.at[idx, final_col] = str(sample_size - 1)

    # Pass 2: enforce uniqueness and organic jitter using INTEGER noise (no decimals)
    # Global, deterministic integer jitter per brand to preserve cross-category equality
    import hashlib
    def brand_int_delta(brand: str) -> int:
        h = hashlib.sha1(brand.encode('utf-8')).hexdigest()
        v = int(h[-4:], 16)  # 0..65535
        delta = (v % 15) - 7  # range -7..+7
        return delta if delta != 0 else 1

    # Build base integer-adjusted value per brand
    brand_adjusted_value = {}
    for brand, base_val in brand_max_raw.items():
        delta = brand_int_delta(brand)
        adj = base_val + delta
        if adj < 1:
            adj = 1
        if sample_size is not None and brand not in brand_input_brands and adj == sample_size:
            adj = max(1, sample_size - 1)
        brand_adjusted_value[brand] = adj

    # Apply initial integer-adjusted values globally
    for idx, row in df.iterrows():
        col = str(row.get('Column', '')).upper()
        if col in ['INPUT_METADATA', 'SAMPLE SIZE', 'PURCHASE SHARE', 'BRAND PENETRATION']:
            continue
        brand = str(row.get('Value', '')).strip().upper()
        if brand in brand_adjusted_value:
            df.at[idx, final_col] = str(int(brand_adjusted_value[brand]))

    # Reset index to avoid duplicate-index issues from concatenation
    df = df.reset_index(drop=True)

    # Vectorized category-level de-duplication WITHOUT while-loops
    # Define excluded columns once for reuse
    excluded_cols = set(['INPUT_METADATA', 'SAMPLE SIZE', 'PURCHASE SHARE', 'BRAND PENETRATION'])
    # Step A: apply current brand_adjusted_value globally
    mask_all = ~df['Column'].str.upper().isin(list(excluded_cols))
    mapped_raw = (
        df.loc[mask_all, 'Value'].astype(str).str.upper()
        .map(lambda b: str(int(brand_adjusted_value.get(b, 1))))
    )
    df.loc[mask_all, final_col] = mapped_raw.values

    # Step B: detect duplicates per category on integers
    import pandas as pd
    work = df.loc[mask_all, ['Column', 'Value', final_col]].copy()
    work['brand_up'] = work['Value'].astype(str).str.upper()
    work['raw_int'] = pd.to_numeric(work[final_col].astype(str).str.replace(',', ''), errors='coerce').fillna(0).astype(int)
    dup_flags = work.duplicated(subset=['Column', 'raw_int'], keep=False)
    dups = work[dup_flags]

    if not dups.empty:
        # Compute deterministic small extra bump per brand (brand-specific to preserve cross-category equality)
        def small_extra(brand: str) -> int:
            h = hashlib.sha1((brand + '|extra').encode('utf-8')).hexdigest()
            r = int(h[-3:], 16) % 5  # 0..4
            val = [-2, -1, 1, 2, 3][r]
            return val

        # Determine per-brand extra across all its duplicate appearances (max to satisfy all categories)
        brand_to_extra = {}
        for b in dups['brand_up'].unique():
            brand_to_extra[b] = small_extra(b)

        # Build final per-brand value with extra and clamp
        new_brand_value = {}
        for b, base_val in brand_adjusted_value.items():
            extra = brand_to_extra.get(b, 0)
            v = int(base_val) + int(extra)
            if v < 1:
                v = 1
            if sample_size is not None and b not in brand_input_brands and v == sample_size:
                v = max(1, sample_size - 1)
            new_brand_value[b] = v
        brand_adjusted_value = new_brand_value

        # Apply new mapping globally in one pass
        mapped_final = (
            df.loc[mask_all, 'Value'].astype(str).str.upper()
            .map(lambda b: str(int(brand_adjusted_value.get(b, 1))))
        )
        df.loc[mask_all, final_col] = mapped_final.values

    # Ensure integers as strings (no decimals) and re-apply sample-size rule
    if sample_size is not None:
        for idx, row in df.iterrows():
            col = str(row.get('Column', '')).upper()
            if col in excluded_cols:
                continue
            brand_name = str(row.get('Value', '')).strip().upper()
            try:
                raw_num = int(float(str(row.get(final_col, '')).replace(',', '')))
            except Exception:
                continue
            if raw_num == sample_size and brand_name not in brand_input_brands:
                df.at[idx, final_col] = str(sample_size - 1)
            else:
                df.at[idx, final_col] = str(int(max(1, raw_num)))

    # Special rule: NETFLIX in STREAMING/PLATFORM(S) must be strictly above 54% of sample size
    # Use a random integer bump (never just +1) and clamp below sample size
    if sample_size is not None and sample_size > 0:
        import math
        platform_mask = df['Column'].str.upper().isin(['STREAMING/PLATFORM', 'STREAMING/PLATFORMS'])
        netflix_mask = df['Value'].str.contains('netflix', case=False, na=False)
        mask = platform_mask & netflix_mask
        if mask.any():
            threshold = int(math.ceil(sample_size * 0.54))  # 54% floor
            for idx in df[mask].index:
                try:
                    current_val = int(float(str(df.at[idx, final_col]).replace(',', '')))
                except Exception:
                    current_val = 0
                if current_val <= threshold:  # force strictly above 54%
                    # Random bump between +2 and +0.4% of sample (at least 2)
                    bump_min = 2
                    bump_max = max(bump_min, int(sample_size * 0.004))
                    bump = random.randint(bump_min, bump_max)
                    new_val = threshold + bump
                    if new_val >= sample_size:
                        new_val = sample_size - 1
                    df.at[idx, final_col] = str(new_val)
                elif current_val == threshold + 1:
                    # If exactly threshold+1, nudge further by a small random amount
                    bump = random.randint(1, max(2, int(sample_size * 0.002)))
                    new_val = current_val + bump
                    if new_val >= sample_size:
                        new_val = sample_size - 1
                    df.at[idx, final_col] = str(new_val)

    return df

def rescale_percentages_by_original_raw_top(df, target_top=75.0):
    """
    For each behavioral category, rescale percentages from final 'Original Raw Numbers' using:
        new_pct = (raw / max_raw) * (base + ln(max_raw + 1))

    - Where max_raw is the highest 'Original Raw Numbers' within that category
    - Uses natural log
    - Category-specific base values to prevent over-inflation:
      * WHERE THEY SHOP, QSR, APP/PLATFORM USAGE: base=40 (to prevent 80-90% inflation)
      * All other categories: base=75 (original behavior)
    - Skips derived/non-behavior categories (demographics, sample/meta, purchase/penetration)
    """
    import pandas as pd
    import math

    if 'Original Raw Numbers' not in df.columns:
        return df

    # Skip non-behavior categories, including all demographics
    behavior_skip = set([
        'INPUT_METADATA', 'SAMPLE SIZE', 'TOTAL USERS WHO PURCHASED', 'PURCHASE SHARE', 'BRAND PENETRATION',
        'GENDER', 'AGE', 'ETHNICITY', 'INCOME', 'EDUCATION', 'RELATIONSHIP',
        'SEXUAL_ORIENTATION', 'PARENTAL_STATUS', 'LOCATION', 'OCCUPATION'
    ])

    # Categories that should use lower base (40) to prevent over-inflation
    # These categories were showing 80-90% which is too high
    lower_base_categories = {
        'WHERE THEY SHOP',
        'QSR',  # Quick Service Restaurant category
        'APP/PLATFORM USAGE',
        'APP/PLATFORMS CASUAL DINING',  # Handle variations
        'CASUAL DINING'
    }
    
    # Work category by category
    for category in df['Column'].unique():
        cat_name = str(category).upper()
        if cat_name in behavior_skip:
            continue
        cat_mask = df['Column'] == category
        if not cat_mask.any():
            continue
        # numeric raw values
        # Use the correct column name that exists at this point in the pipeline
        raw_col = 'Original Raw Numbers (Database)' if 'Original Raw Numbers (Database)' in df.columns else 'Original Raw Numbers'
        raw_series = pd.to_numeric(df.loc[cat_mask, raw_col].astype(str).str.replace(',', ''), errors='coerce')
        if raw_series.isna().all():
            continue
        # Identify top raw; if zero/NaN skip
        top_raw = raw_series.max(skipna=True)
        if pd.isna(top_raw) or top_raw <= 0:
            continue
        
        # Determine base value based on category
        # Check if category matches any of the lower_base_categories (case-insensitive)
        use_lower_base = cat_name in lower_base_categories or any(
            lower_base_cat.replace('/', '').replace(' ', '') in cat_name.replace('/', '').replace(' ', '') or
            cat_name.replace('/', '').replace(' ', '') in lower_base_cat.replace('/', '').replace(' ', '')
            for lower_base_cat in lower_base_categories
        )
        
        base_value = 40.0 if use_lower_base else 75.0
        
        # Compute target top per category: (base + ln(max_raw + 1))
        target_top_dynamic = base_value + math.log(float(top_raw) + 1.0)
        # Compute scaled percentages from raw ratios
        ratios = raw_series.fillna(0.0).astype(float) / float(top_raw)
        new_percentages = ratios * target_top_dynamic
        # Apply
        df.loc[cat_mask, 'Percentage'] = new_percentages.values

    return df

def enforce_tumblr_cap_social(df):
    """Clamp TUMBLR in SOCIAL MEDIA to the range [2, 5] percent."""
    import pandas as pd
    mask = (df['Column'].str.upper() == 'SOCIAL MEDIA') & (
        df['Value'].str.contains('tumblr', case=False, na=False)
    )
    if not mask.any():
        return df
    # Coerce to float and clamp
    df.loc[mask, 'Percentage'] = pd.to_numeric(df.loc[mask, 'Percentage'], errors='coerce')
    df.loc[mask, 'Percentage'] = df.loc[mask, 'Percentage'].clip(lower=2.0, upper=5.0)
    return df

def enforce_goop_cap_media(df):
    """Clamp GOOP in MEDIA to the range [2, 8] percent."""
    import pandas as pd
    mask = (df['Column'].str.upper() == 'MEDIA') & (
        df['Value'].str.contains('goop', case=False, na=False)
    )
    if not mask.any():
        return df
    df.loc[mask, 'Percentage'] = pd.to_numeric(df.loc[mask, 'Percentage'], errors='coerce')
    df.loc[mask, 'Percentage'] = df.loc[mask, 'Percentage'].clip(lower=2.0, upper=8.0)
    return df

def enforce_search_engine_google_top(df: pd.DataFrame) -> pd.DataFrame:
    """Disabled: No special ordering rules per user request."""
    return df

def sort_search_engine_by_raw_desc(df: pd.DataFrame) -> pd.DataFrame:
    """Sort SEARCH ENGINE and SEARCH ENGINE/AI category rows by 'Original Raw Numbers' descending.

    Only reorders rows within those categories; leaves other categories and their positions untouched.
    """
    import pandas as pd
    if df is None or df.empty:
        return df
    df = df.copy()
    col_upper = df['Column'].astype(str).str.upper()
    cat_mask = (col_upper == 'SEARCH ENGINE') | (col_upper == 'SEARCH ENGINE/AI')
    if not cat_mask.any() or 'Original Raw Numbers' not in df.columns:
        return df
    seg = df.loc[cat_mask].copy()
    raw_col = 'Original Raw Numbers (Database)' if 'Original Raw Numbers (Database)' in seg.columns else 'Original Raw Numbers'
    seg['RAW'] = pd.to_numeric(seg[raw_col].astype(str).str.replace(',', ''), errors='coerce').fillna(0)
    seg_sorted = seg.sort_values(by='RAW', ascending=False).drop(columns=['RAW'])
    # Write sorted rows back into original positions so category block stays in place
    cols = [c for c in df.columns if c in seg_sorted.columns]
    df.loc[cat_mask, cols] = seg_sorted[cols].values
    return df

def sort_streaming_platform_by_raw_desc(df: pd.DataFrame) -> pd.DataFrame:
    """Sort STREAMING/PLATFORM(S) category rows by 'Original Raw Numbers' descending.

    Only reorders rows within those categories; leaves other categories untouched.
    """
    import pandas as pd
    if df is None or df.empty:
        return df
    df = df.copy()
    if 'Original Raw Numbers' not in df.columns:
        return df
    col_up = df['Column'].astype(str).str.upper()
    mask = col_up.isin(['STREAMING/PLATFORM', 'STREAMING/PLATFORMS'])
    if not mask.any():
        return df
    seg = df.loc[mask].copy()
    # Use the correct column name that exists at this point in the pipeline
    raw_col = 'Original Raw Numbers (Database)' if 'Original Raw Numbers (Database)' in seg.columns else 'Original Raw Numbers'
    seg['RAW'] = pd.to_numeric(seg[raw_col].astype(str).str.replace(',', ''), errors='coerce').fillna(0)
    seg_sorted = seg.sort_values(by='RAW', ascending=False).drop(columns=['RAW'])
    non_seg = df.loc[~mask]
    df_sorted = pd.concat([non_seg, seg_sorted], axis=0)
    df_sorted = df_sorted[df.columns]
    return df_sorted

def enforce_streaming_music_top6(df):
    """Ensure Spotify, YouTube Music, Apple Music, Amazon Music, SiriusXM, and Pandora Music are in top 6 of STREAMING/MUSIC."""
    required_brands = [
        'SPOTIFY', 'YOUTUBE MUSIC', 'APPLE MUSIC', 
        'AMAZON MUSIC', 'SIRIUSXM', 'PANDORA MUSIC'
    ]
    
    # Find STREAMING/MUSIC category
    mask = df['Column'].str.upper() == 'STREAMING/MUSIC'
    if not mask.any():
        return df
    
    category_df = df[mask].copy()
    category_df['__pct'] = pd.to_numeric(category_df['Percentage'], errors='coerce').fillna(0)
    
    # Find required brands in the category
    required_found = []
    required_indices = []
    for idx, row in category_df.iterrows():
        brand = str(row['Value']).upper().strip()
        if brand in required_brands:
            required_found.append(brand)
            required_indices.append(idx)
    
    if len(required_found) == 0:
        return df
    
    # Get top 6 positions by percentage
    category_df = category_df.sort_values('__pct', ascending=False)
    top6_indices = category_df.head(6).index.tolist()
    
    # Check if any required brands are outside top 6
    required_outside = [idx for idx in required_indices if idx not in top6_indices]
    non_required_in_top6 = [idx for idx in top6_indices if idx not in required_indices]
    
    if len(required_outside) == 0:
        return df  # All required brands already in top 6
    
    # Sort required brands by their current percentage (descending)
    required_outside_sorted = sorted(required_outside, 
                                   key=lambda i: float(df.at[i, 'Percentage']), 
                                   reverse=True)
    
    # Sort non-required brands in top 6 by their percentage (ascending - swap with lowest first)
    non_required_sorted = sorted(non_required_in_top6, 
                               key=lambda i: float(df.at[i, 'Percentage']))
    
    # Perform swaps to move required brands into top 6
    swaps = min(len(required_outside_sorted), len(non_required_sorted))
    for i in range(swaps):
        req_idx = required_outside_sorted[i]
        non_req_idx = non_required_sorted[i]
        
        # Swap their percentages
        temp = df.at[req_idx, 'Percentage']
        df.at[req_idx, 'Percentage'] = df.at[non_req_idx, 'Percentage']
        df.at[non_req_idx, 'Percentage'] = temp
        
        if not SILENCE_VERBOSE_OUTPUT:
            print(f"🔄 Swapped {df.at[req_idx, 'Value']} into top 6 of STREAMING/MUSIC")
    
    return df


def _parse_ai_json_response(text: str):
    """Extract first JSON object from model output (handles markdown fences)."""
    import json as _json
    text = (text or '').strip()
    if text.startswith('```'):
        text = text.split('\n', 1)[1].rsplit('```', 1)[0].strip()
    depth = 0
    end = 0
    for i, c in enumerate(text):
        if c == '{':
            depth += 1
        elif c == '}':
            depth -= 1
            if depth == 0:
                end = i + 1
                break
    if end > 0:
        text = text[:end]
    return _json.loads(text)


def finalize_output_metrics_like_edit_sample_size(df: pd.DataFrame) -> pd.DataFrame:
    """Last-step math: BP × sample_size → Original Raw; within-category Category Share;
    then US Gen Pop from raws. Same order as ``edit_sample_size.py`` / reconcile."""
    if df is None or df.empty:
        return df
    df = reconcile_final_output_from_bp_and_sample_size(df)
    df = add_us_gen_pop_projection(df)
    return df


def enforce_income_buckets_whitelist(df: pd.DataFrame) -> pd.DataFrame:
    """
    Restrict INCOME rows to approved final-output buckets only, aggregating any
    non-standard income ranges into the nearest allowed bucket.
    """
    if df is None or df.empty:
        return df
    if 'Column' not in df.columns or 'Value' not in df.columns:
        return df

    out = df.copy()
    bp_col = 'Brand Penetration (Row)' if 'Brand Penetration (Row)' in out.columns else None
    cs_col = 'Category Share' if 'Category Share' in out.columns else (
        'Percentage' if 'Percentage' in out.columns else None
    )
    pct_col = 'Percentage' if 'Percentage' in out.columns else cs_col
    raw_col = 'Original Raw Numbers' if 'Original Raw Numbers' in out.columns else None
    proj_col = 'US Gen Pop Projection' if 'US Gen Pop Projection' in out.columns else None
    MULT = 329_900_000 / 10_000_000

    if not bp_col or not cs_col:
        return out

    def _to_num(v, default=0.0):
        try:
            return float(str(v).replace(',', '').replace('%', '').strip())
        except Exception:
            return default

    def _to_int(v, default=0):
        try:
            return int(round(float(str(v).replace(',', '').replace('%', '').strip())))
        except Exception:
            return default

    allowed = [
        '$25,000 - $49,999',
        '$50,000 - $74,999',
        '$75,000 - $99,999',
        '$100,000 - $149,999',
        '$150,000 - $249,999',
        '$250,000 OR MORE',
    ]

    def _parse_money_range(v: str):
        s = str(v or '').upper().replace(',', '').strip()
        s = s.replace('K', '000')
        nums = [int(x) for x in re.findall(r'\d+', s)]
        if ('UNDER' in s or '<' in s) and nums:
            hi = nums[0]
            return 0, max(0, hi - 1)
        if ('OR MORE' in s or '+' in s or 'AND OVER' in s) and nums:
            lo = nums[0]
            return lo, None
        if len(nums) >= 2:
            lo, hi = min(nums[0], nums[1]), max(nums[0], nums[1])
            return lo, hi
        if len(nums) == 1:
            n = nums[0]
            return n, n
        return None, None

    def _canon_income(v: str) -> str:
        lo, hi = _parse_money_range(v)
        if lo is None:
            return '$25,000 - $49,999'
        if hi is None:
            return '$250,000 OR MORE' if lo >= 250000 else '$150,000 - $249,999'
        mid = (lo + hi) / 2.0
        if mid >= 250000:
            return '$250,000 OR MORE'
        if mid >= 150000:
            return '$150,000 - $249,999'
        if mid >= 100000:
            return '$100,000 - $149,999'
        if mid >= 75000:
            return '$75,000 - $99,999'
        if mid >= 50000:
            return '$50,000 - $74,999'
        # Includes under-$25k/low bins by user-request bucket policy.
        return '$25,000 - $49,999'

    income_mask = out['Column'].astype(str).str.upper().str.strip() == 'INCOME'
    if not income_mask.any():
        return out

    sample_size = 0
    ss_mask = out['Column'].astype(str).str.upper().str.strip() == 'SAMPLE SIZE'
    if raw_col and ss_mask.any():
        sample_size = _to_int(out.loc[ss_mask, raw_col].iloc[0], 0)
    if sample_size <= 0 and cs_col and ss_mask.any():
        sample_size = _to_int(out.loc[ss_mask, cs_col].iloc[0], 0)

    income_rows = out[income_mask].copy()
    template = income_rows.iloc[0].to_dict()
    bucket_raw = {k: 0 for k in allowed}

    for _, row in income_rows.iterrows():
        bucket = _canon_income(row.get('Value', ''))
        raw = _to_int(row.get(raw_col, 0), 0) if raw_col else 0
        if raw <= 0 and sample_size > 0:
            raw = max(0, int(round((_to_num(row.get(bp_col, 0), 0.0) / 100.0) * sample_size)))
        bucket_raw[bucket] += max(0, raw)

    total_raw = sum(bucket_raw.values())
    if total_raw <= 0:
        return out

    out = out[~income_mask].copy()
    rebuilt = []
    for bucket in allowed:
        r = bucket_raw[bucket]
        if r <= 0:
            continue
        pct = round((r / total_raw) * 100.0, 4)
        row = dict(template)
        row['Column'] = 'INCOME'
        row['Value'] = bucket
        row[bp_col] = f"{pct:.4f}"
        row[cs_col] = f"{pct:.4f}"
        if pct_col in row:
            row[pct_col] = f"{pct:.4f}"
        if raw_col:
            row[raw_col] = str(int(r))
        if proj_col:
            row[proj_col] = str(int(round(int(r) * MULT)))
        rebuilt.append(row)

    out = pd.concat([out, pd.DataFrame(rebuilt)], ignore_index=True)
    return out


def ensure_bp_driven_metric_alignment(df: pd.DataFrame) -> pd.DataFrame:
    """
    Final safety gate for BP-driven consistency.

    Verifies that:
    - Original Raw Numbers == round((BP / 100) * sample_size)
    - Category Share == row_raw / category_raw_sum * 100 (4dp)

    If drift is detected, auto-runs the canonical reconcile + projection pass.
    """
    if df is None or df.empty:
        return df
    required = {'Column', 'Brand Penetration (Row)', 'Original Raw Numbers'}
    if not required.issubset(df.columns):
        return df
    pct_col = 'Category Share' if 'Category Share' in df.columns else (
        'Percentage' if 'Percentage' in df.columns else None)
    if pct_col is None:
        return df

    def _to_float(x, default=0.0):
        try:
            return float(str(x).replace(',', '').replace('%', '').strip())
        except Exception:
            return default

    def _to_int(x, default=0):
        try:
            return int(round(float(str(x).replace(',', '').replace('%', '').strip())))
        except Exception:
            return default

    # Resolve sample size exactly like reconcile path
    sample_size = 0
    ss_mask = df['Column'].astype(str).str.upper().str.strip() == 'SAMPLE SIZE'
    if ss_mask.any():
        sidx = df[ss_mask].index[0]
        sample_size = _to_int(df.at[sidx, 'Original Raw Numbers'], 0)
        if sample_size <= 0:
            sample_size = _to_int(df.at[sidx, pct_col], 0)
    if sample_size <= 0:
        bi_mask = df['Column'].astype(str).str.upper().str.strip() == 'BRAND INPUT'
        if bi_mask.any():
            sample_size = _to_int(df.loc[bi_mask, 'Original Raw Numbers'].iloc[0], 0)
    if sample_size <= 0:
        return df

    skip = {
        'INPUT_METADATA', 'BRAND INPUT', 'SAMPLE SIZE', 'AVID FAN', 'CASUAL FAN', 'BRAND CATEGORY'
    }
    out = df.copy()
    cat_keys = out['Column'].astype(str).str.upper().str.strip()
    raw_mismatch = 0
    cs_mismatch = 0

    # Validate raw from BP
    for idx in out.index:
        cat = str(out.at[idx, 'Column']).strip().upper()
        if cat in skip:
            continue
        bp = _to_float(out.at[idx, 'Brand Penetration (Row)'], 0.0)
        expected_raw = int(round((bp / 100.0) * sample_size))
        actual_raw = _to_int(out.at[idx, 'Original Raw Numbers'], 0)
        if expected_raw != actual_raw:
            raw_mismatch += 1

    # Validate category share from raw
    for cat in cat_keys.unique():
        if cat in skip:
            continue
        idxs = list(out[cat_keys == cat].index)
        if not idxs:
            continue
        cat_sum = sum(_to_int(out.at[i, 'Original Raw Numbers'], 0) for i in idxs)
        if cat_sum <= 0:
            continue
        for i in idxs:
            expected_cs = round((_to_int(out.at[i, 'Original Raw Numbers'], 0) / cat_sum) * 100.0, 4)
            actual_cs = round(_to_float(out.at[i, pct_col], 0.0), 4)
            if expected_cs != actual_cs:
                cs_mismatch += 1

    if raw_mismatch or cs_mismatch:
        if not SILENCE_VERBOSE_OUTPUT:
            print(
                f"🔁 Final alignment guard: detected drift "
                f"(raw mismatches={raw_mismatch}, share mismatches={cs_mismatch}) "
                f"→ re-running reconcile"
            )
        out = reconcile_final_output_from_bp_and_sample_size(out)
        out = add_us_gen_pop_projection(out)
    return out


def enforce_pipeline_sanity_guards(df: pd.DataFrame, is_genpop: bool = False, brand_category: str = None) -> pd.DataFrame:
    """
    Guardrail for catastrophic numeric regressions.

    - For non-GenPop runs, enforce a minimum practical sample size floor.
    - Clamp non-metadata Brand Penetration rows to valid range [0.0001, 99.9999].
    - Recompute raw/category-share/projection after corrections.
    """
    if df is None or df.empty:
        return df
    if 'Column' not in df.columns:
        return df
    if 'Brand Penetration (Row)' not in df.columns:
        return df

    out = df.copy()
    bp_col = 'Brand Penetration (Row)'
    pct_col = 'Category Share' if 'Category Share' in out.columns else (
        'Percentage' if 'Percentage' in out.columns else None)
    raw_col = 'Original Raw Numbers' if 'Original Raw Numbers' in out.columns else None
    proj_col = 'US Gen Pop Projection' if 'US Gen Pop Projection' in out.columns else None

    if pct_col is None or raw_col is None:
        return out

    def _to_float(x, default=0.0):
        try:
            return float(str(x).replace(',', '').replace('%', '').strip())
        except Exception:
            return default

    def _to_int(x, default=0):
        try:
            return int(round(float(str(x).replace(',', '').replace('%', '').strip())))
        except Exception:
            return default

    cat_keys = out['Column'].astype(str).str.upper().str.strip()
    meta = {'INPUT_METADATA', 'BRAND INPUT', 'SAMPLE SIZE', 'AVID FAN', 'CASUAL FAN', 'BRAND CATEGORY'}

    # 1) Sample-size sanity (non-GenPop only)
    if not is_genpop:
        ss_mask = cat_keys == 'SAMPLE SIZE'
        if ss_mask.any():
            sidx = out[ss_mask].index[0]
            sample_size = _to_int(out.at[sidx, raw_col], 0)
            if sample_size <= 0:
                sample_size = _to_int(out.at[sidx, pct_col], 0)
            if sample_size < 1000:
                estimated = estimate_sample_size_for_unknown_brand(brand_category or '', None)
                sample_size = max(10_000, estimated)
                out.at[sidx, raw_col] = str(sample_size)
                out.at[sidx, pct_col] = str(sample_size)
                if proj_col:
                    out.at[sidx, proj_col] = str(int(round((sample_size / 10_000_000) * 329_900_000)))
                bi_mask = cat_keys == 'BRAND INPUT'
                if bi_mask.any():
                    bidx = out[bi_mask].index[0]
                    out.at[bidx, raw_col] = str(sample_size)
                    if proj_col:
                        out.at[bidx, proj_col] = str(int(round((sample_size / 10_000_000) * 329_900_000)))
                if not SILENCE_VERBOSE_OUTPUT:
                    print(f"🛡️ Sample-size sanity guard: raised SAMPLE SIZE to {sample_size:,}")

    # 2) BP sanity clamp for non-metadata rows
    clamped = 0
    for i in out.index:
        c = str(out.at[i, 'Column']).strip().upper()
        if c in meta:
            continue
        v = _to_float(out.at[i, bp_col], 0.0)
        nv = max(0.0001, min(99.9999, v))
        if abs(nv - v) > 1e-9:
            out.at[i, bp_col] = f"{nv:.4f}"
            clamped += 1

    if clamped and not SILENCE_VERBOSE_OUTPUT:
        print(f"🛡️ BP sanity guard: clamped {clamped} out-of-range BP value(s)")

    # 3) Recompute dependent metrics to keep alignment strict
    out = reconcile_final_output_from_bp_and_sample_size(out)
    out = add_us_gen_pop_projection(out)
    return out


def ai_review_most_purchased_brands_vs_genpop(
        df: pd.DataFrame,
        project_name: str,
        brands,
        brand_category: str,
        is_genpop: bool) -> tuple:
    """Row-by-row GPT-4o review of MOST PURCHASED BRANDS vs US Gen Pop + persona.

    Flags implausible over-index (e.g. La Roche-Posay, Tory Burch on male-skewing /
    sports audiences) and returns corrected BP. Caller should run
    ``finalize_output_metrics_like_edit_sample_size`` after all BP edits.
    """
    if is_genpop or df is None or df.empty:
        return df, 0
    bp_col = 'Brand Penetration (Row)' if 'Brand Penetration (Row)' in df.columns else None
    if not bp_col:
        return df, 0
    mpb_mask = df['Column'].str.upper().str.strip() == 'MOST PURCHASED BRANDS'
    if not mpb_mask.any():
        return df, 0

    client = _get_openai_client()
    if not client:
        return df, 0

    gp_ref = _load_genpop_csv()
    gp_bp_map = {}
    if gp_ref is not None:
        try:
            _c0, _c1, _c2 = gp_ref.columns[0], gp_ref.columns[1], gp_ref.columns[2]
            for _, _gr in gp_ref.iterrows():
                _gc = str(_gr[_c0]).strip().upper()
                _gv = str(_gr[_c1]).strip().upper()
                try:
                    gp_bp_map[(_gc, _gv)] = float(_gr[_c2])
                except (ValueError, TypeError):
                    pass
        except Exception:
            gp_bp_map = {}

    subject = extract_profile_subject_from_df(df, project_name, brands)
    bc = (brand_category or '').strip()
    profile_summary = _build_profile_summary(df)

    rows = []
    for idx in df[mpb_mask].index:
        val = str(df.at[idx, 'Value']).strip()
        try:
            bp = float(str(df.at[idx, bp_col]).replace(',', '').replace('%', ''))
        except (ValueError, TypeError):
            continue
        gpk = ('MOST PURCHASED BRANDS', val.upper())
        gp_bp = gp_bp_map.get(gpk, 0.0)
        idx_mult = (bp / gp_bp) if gp_bp > 0 else None
        rows.append((idx, val, bp, gp_bp, idx_mult))

    if not rows:
        return df, 0

    adjustments = 0
    batch_size = 22
    for b_start in range(0, len(rows), batch_size):
        batch = rows[b_start:b_start + batch_size]
        lines = []
        for _i, (_idx, _name, _bp, _gp, _im) in enumerate(batch, 1):
            if _gp and _gp > 0:
                im_s = f", GenPop={_gp:.2f}%, index≈{_bp/_gp:.2f}x" if _im else ''
            else:
                im_s = ", GenPop baseline N/A"
            lines.append(f"  {_i}. {_name}: profile BP={_bp:.4f}%{im_s}")

        prompt = (
            f"You are a senior consumer insights director. Audience: \"{subject}\" "
            f"({bc}).\n\n"
            f"DEMO / PERSONA (use for every judgment):\n{profile_summary[:2500]}\n\n"
            f"=== MOST PURCHASED BRANDS — ROW BY ROW ===\n"
            f"Each line is ONE brand. \"profile BP\" = % of THIS audience panel estimated "
            f"to have purchased that brand in the study window. \"GenPop\" = US general "
            f"population baseline % for the same row when available.\n\n"
            + "\n".join(lines) +
            f"\n\n=== YOUR TASK ===\n"
            f"For EACH brand above, decide if the profile BP is believable for this audience.\n"
            f"- Brands that skew female / prestige skincare / women's luxury (e.g. La Roche-Posay, "
            f"Tory Burch, Fenty, Sephora-heavy labels) should NOT sit far ABOVE US Gen Pop on a "
            f"male-skewing or sports/entertainment audience unless you can justify a small lift "
            f"(typically cap near min(profile, max(GenPop×1.15, GenPop+0.5)) when GenPop exists; "
            f"if GenPop missing, use persona: often single-digit to low teens for niche luxury "
            f"women's brands on male-skew profiles).\n"
            f"- Mass brands (Nike, Amazon, Walmart, Coke) can index higher; still cap any single "
            f"row at 90% BP.\n"
            f"- If the current BP is fine, return the SAME value (or within 0.01).\n"
            f"- You MUST return one entry per line number / brand — no skipping.\n\n"
            f"Return ONLY valid JSON:\n"
            f'{{"corrections":[{{"item":"BRAND NAME EXACT",'
            f'"correct_bp":12.3456,"reason":"brief"}},...]}}\n'
            f"JSON only, no markdown."
        )

        try:
            resp = client.chat.completions.create(
                model='gpt-4o',
                messages=[{'role': 'user', 'content': prompt}],
                temperature=0.12,
                max_tokens=8000,
            )
            result = _parse_ai_json_response(resp.choices[0].message.content.strip())
            for corr in result.get('corrections', []):
                try:
                    ci = str(corr.get('item', '')).strip().upper()
                    cnew = float(corr.get('correct_bp', 0))
                    _reason = str(corr.get('reason', ''))[:120]
                except (ValueError, TypeError):
                    continue
                cnew = max(0.05, min(cnew, 90.0))
                cnew = round(cnew, 4)
                matched_idx = None
                matched_old = None
                for _idx, _name, _bp, _gp, _ in batch:
                    nu = _name.strip().upper()
                    if nu == ci or ci in nu or nu in ci:
                        matched_idx, matched_old = _idx, _bp
                        break
                if matched_idx is None:
                    continue
                if abs(cnew - matched_old) < 0.25:
                    continue
                # Only set BP; reconcile_final_output_from_bp_and_sample_size + genpop
                # will recompute Original Raw Numbers, Category Share, and projection.
                df.at[matched_idx, bp_col] = f"{cnew:.4f}"
                adjustments += 1
                print(f"   🛒 MPB review ↕ {df.at[matched_idx, 'Value']}: "
                      f"{matched_old:.2f}%→{cnew:.4f}% — {_reason}")
        except Exception as _e:
            print(f"   ⚠️ MOST PURCHASED BRANDS AI review error: {_e}")

    if adjustments:
        print(f"   🛒 MOST PURCHASED BRANDS persona+GenPop review: {adjustments} rows adjusted")
    return df, adjustments


def reconcile_final_output_from_bp_and_sample_size(df: pd.DataFrame) -> pd.DataFrame:
    """Align Original Raw Numbers and Category Share with Brand Penetration and panel sample size.

    Mirrors ``edit_sample_size.py`` (same math / order):
      1. Resolve sample size from SAMPLE SIZE (Original Raw Numbers, else Category Share) or
         BRAND INPUT Original Raw Numbers.
      2. Set BRAND INPUT ``Original Raw Numbers`` = sample size; SAMPLE SIZE ``Original Raw
         Numbers`` = sample size; SAMPLE SIZE ``Category Share`` (or ``Percentage``) = sample
         size (spreadsheet convention: D4 holds the panel N).
      3. For every other row: ``Original Raw Numbers`` = round((BP / 100) * sample_size).
      4. Within each ``Column`` category: ``Category Share`` = (row raw / sum raws in category)
         * 100, rounded to 4 decimals.

    Caller should run ``add_us_gen_pop_projection(df)`` immediately after to fill
    ``US Gen Pop Projection`` from Original Raw Numbers.
    """
    if df is None or df.empty:
        return df
    df = df.copy()
    required = {'Column', 'Brand Penetration (Row)', 'Original Raw Numbers'}
    if not required.issubset(df.columns):
        return df
    pct_col = 'Category Share' if 'Category Share' in df.columns else (
        'Percentage' if 'Percentage' in df.columns else None)
    if pct_col is None:
        return df
    bp_col = 'Brand Penetration (Row)'

    def _parse_int(x):
        try:
            return int(round(float(str(x).replace(',', '').replace('%', '').strip())))
        except (ValueError, TypeError):
            return 0

    sample_size = 0
    ss_mask = df['Column'].str.upper().str.strip() == 'SAMPLE SIZE'
    if ss_mask.any():
        sidx = df[ss_mask].index[0]
        sample_size = _parse_int(df.at[sidx, 'Original Raw Numbers'])
        if sample_size <= 0:
            sample_size = _parse_int(df.at[sidx, pct_col])
    if sample_size <= 0:
        bi_mask = df['Column'].str.upper().str.strip() == 'BRAND INPUT'
        if bi_mask.any():
            sample_size = _parse_int(df.loc[bi_mask, 'Original Raw Numbers'].iloc[0])
    if sample_size <= 0:
        print("   ⚠️ reconcile_final_output_from_bp_and_sample_size: no valid sample size; skip")
        return df

    skip_bp_to_raw = {
        'INPUT_METADATA', 'BRAND INPUT', 'SAMPLE SIZE', 'AVID FAN', 'CASUAL FAN',
        'BRAND CATEGORY',
    }
    skip_cs_cats = set(skip_bp_to_raw)

    bi_mask = df['Column'].str.upper().str.strip() == 'BRAND INPUT'
    if bi_mask.any():
        df.loc[bi_mask, 'Original Raw Numbers'] = str(sample_size)
    if ss_mask.any():
        sidx = df[ss_mask].index[0]
        df.at[sidx, 'Original Raw Numbers'] = str(sample_size)
        df.at[sidx, pct_col] = str(sample_size)

    rows_updated = 0
    for idx in df.index:
        col_u = str(df.at[idx, 'Column']).strip().upper()
        if col_u in skip_bp_to_raw:
            continue
        try:
            pv = df.at[idx, bp_col]
            if isinstance(pv, str):
                pv = pv.replace('%', '').replace(',', '').strip()
            penetration = float(pv)
            new_raw = int(round((penetration / 100.0) * sample_size))
            df.at[idx, 'Original Raw Numbers'] = str(new_raw)
            rows_updated += 1
        except (ValueError, TypeError):
            continue

    cat_groups = {}
    for idx in df.index:
        cu = str(df.at[idx, 'Column']).strip().upper()
        cat_groups.setdefault(cu, []).append(idx)

    cats_updated = 0
    for cu, indices in cat_groups.items():
        if cu in skip_cs_cats:
            continue
        category_sum = 0
        valid = []
        for idx in indices:
            rn = _parse_int(df.at[idx, 'Original Raw Numbers'])
            category_sum += rn
            valid.append(idx)
        if category_sum <= 0:
            continue
        for idx in valid:
            raw_num = _parse_int(df.at[idx, 'Original Raw Numbers'])
            share = round((raw_num / category_sum) * 100.0, 4)
            df.at[idx, pct_col] = f"{share:.4f}"

        # De-template repeated decimal tails (e.g., many *.0098) inside a category.
        # Keep category sum at exactly 100.0000 via anchor compensation.
        try:
            cur_vals = {}
            for idx in valid:
                try:
                    cur_vals[idx] = float(str(df.at[idx, pct_col]).replace(',', '').replace('%', '').strip())
                except (ValueError, TypeError):
                    cur_vals[idx] = 0.0

            # 1) Break exact duplicate 4dp values (keep first; jitter rest)
            dup_groups = {}
            for idx in valid:
                v4 = round(cur_vals.get(idx, 0.0), 4)
                dup_groups.setdefault(v4, []).append(idx)

            # 2) Break repeated decimal suffixes across different whole/integer parts
            #    (e.g., 3.0098, 7.0098, 12.0098).
            suffix_groups = {}
            for idx in valid:
                s = f"{round(cur_vals.get(idx, 0.0), 4):.4f}"
                suf = s.split('.')[-1]
                suffix_groups.setdefault(suf, []).append(idx)

            to_adjust = []
            for _v, members in dup_groups.items():
                if len(members) > 1:
                    to_adjust.extend(members[1:])
            for _suf, members in suffix_groups.items():
                if len(members) >= 3:
                    to_adjust.extend(members[1:])

            # Preserve stable order and deduplicate
            seen_adj = set()
            ordered_adjust = []
            for idx in to_adjust:
                if idx in seen_adj:
                    continue
                seen_adj.add(idx)
                ordered_adjust.append(idx)

            if ordered_adjust:
                compensation = 0.0
                adjusted = set()
                for pos, idx in enumerate(ordered_adjust, start=1):
                    old_v = round(cur_vals.get(idx, 0.0), 4)
                    if old_v <= 0:
                        continue
                    delta = ((abs(hash(f"cs-tail-jitter|{cu}|{idx}|{pos}")) % 87) + 1) / 10000.0
                    sign = 1.0 if (abs(hash(f"cs-tail-sign|{cu}|{idx}|{pos}")) % 2) else -1.0
                    if old_v <= (delta + 0.0001):
                        sign = 1.0
                    new_v = round(max(0.0001, min(99.9999, old_v + sign * delta)), 4)
                    if new_v == old_v:
                        new_v = round(min(99.9999, old_v + 0.0001), 4)
                    cur_vals[idx] = new_v
                    compensation = round(compensation + (new_v - old_v), 4)
                    adjusted.add(idx)

                # Offset drift on the largest non-adjusted row if possible.
                candidates = [idx for idx in valid if idx not in adjusted and cur_vals.get(idx, 0.0) > 0]
                if not candidates:
                    candidates = [idx for idx in valid if cur_vals.get(idx, 0.0) > 0]
                if candidates:
                    anchor = max(candidates, key=lambda _i: cur_vals.get(_i, 0.0))
                    cur_vals[anchor] = round(max(0.0001, min(99.9999, cur_vals[anchor] - compensation)), 4)
                    drift = round(100.0 - sum(round(cur_vals.get(i, 0.0), 4) for i in valid), 4)
                    if abs(drift) > 0:
                        cur_vals[anchor] = round(max(0.0001, min(99.9999, cur_vals[anchor] + drift)), 4)

                for idx in valid:
                    df.at[idx, pct_col] = f"{round(cur_vals.get(idx, 0.0), 4):.4f}"
        except Exception:
            pass
        cats_updated += 1

    print(f"   🔗 Reconciled output metrics: sample_size={sample_size:,}, "
          f"raw-from-BP rows={rows_updated}, categories CS={cats_updated}")
    return df


def perturb_brand_penetration_avoid_dot_0000(df: pd.DataFrame) -> pd.DataFrame:
    """Ensure Brand Penetration (Row) never ends in ``.0000`` (four trailing zeros).

    Values formatted to 4 decimals that would read ``X.0000`` get a small uniform bump
    in ``[0.0001, 0.0099]`` (or replacement for true zeros). Rows at ~100%% (platform /
    brand input / sample) are left unchanged. After this, run
    ``reconcile_final_output_from_bp_and_sample_size`` + ``add_us_gen_pop_projection``
    so raws and projections stay consistent with BP.
    """
    if df is None or df.empty or 'Brand Penetration (Row)' not in df.columns:
        return df
    df = df.copy()
    bp_col = 'Brand Penetration (Row)'
    skip_cats = {
        'INPUT_METADATA',
    }
    n_adj = 0
    for idx in df.index:
        cat = str(df.at[idx, 'Column']).strip().upper()
        if cat in skip_cats:
            continue
        try:
            raw_bp = df.at[idx, bp_col]
            if isinstance(raw_bp, str):
                raw_bp = raw_bp.replace('%', '').replace(',', '').strip()
            x = float(raw_bp)
        except (ValueError, TypeError):
            continue
        # Keep intentional 100% rows (platform, brand, sample size, series row, etc.)
        if x >= 99.999:
            df.at[idx, bp_col] = f"{min(x, 100.0):.4f}"
            continue
        x4 = round(x, 4)
        frac_mod = int(round(abs(x4) * 10000 + 1e-9)) % 10000
        if frac_mod != 0:
            df.at[idx, bp_col] = f"{x4:.4f}"
            continue
        # Exactly *.0000 at 4dp (or zero): replace with organic-looking value
        d1 = random.randint(1, 9)
        d2 = random.randint(1, 9)
        d3 = random.randint(1, 9)
        d4 = random.randint(1, 9)
        frac = d1 * 0.1 + d2 * 0.01 + d3 * 0.001 + d4 * 0.0001
        if x4 <= 0:
            new_x = round(frac, 4)
        else:
            integer_part = int(x4)
            new_x = round(integer_part + frac, 4)
            if new_x > 99.9:
                new_x = round(99.0 + frac, 4)
        new_x = max(0.1111, min(round(new_x, 4), 99.8999))
        s = f"{new_x:.4f}"
        df.at[idx, bp_col] = s
        n_adj += 1
    if n_adj:
        print(f"   🎲 Brand Penetration: added micro-variation to {n_adj} "
              f"rows to avoid .0000 endings")
    return df


def add_us_gen_pop_projection(df: pd.DataFrame) -> pd.DataFrame:
    """Add US Gen Pop Projection = (Original Raw Numbers / 10,000,000) * 329,900,000.

    Uses finalized 'Original Raw Numbers'. For SAMPLE SIZE row, uses Category Share/Percentage
    as raw number if Original Raw Numbers is missing. The projected sample size (from SAMPLE SIZE
    row, column D) is placed in BRAND INPUT row (column F).
    """
    import pandas as pd
    US_POPULATION = 329_900_000
    SAMPLE_CAP = 10_000_000
    if df is None or df.empty:
        return df
    df = df.copy()
    if 'Original Raw Numbers' not in df.columns:
        df['US Gen Pop Projection'] = ''
        return df
    raw_col = 'Original Raw Numbers'

    # Handle SAMPLE SIZE row: use Category Share or Percentage as raw number if Original Raw Numbers is missing/empty
    sample_size_mask = df['Column'].str.upper() == 'SAMPLE SIZE'
    if sample_size_mask.any():
        for idx in df[sample_size_mask].index:
            raw_val = df.at[idx, raw_col]
            if pd.isna(raw_val) or str(raw_val).strip() in ('', 'nan', 'NaN', 'None') or float(str(raw_val).replace(',', '')) == 0:
                for col in ['Category Share', 'Percentage']:
                    if col in df.columns:
                        val = df.at[idx, col]
                        try:
                            v = float(str(val).replace(',', '').strip())
                            if v > 0:
                                df.at[idx, raw_col] = str(int(v))
                                break
                        except Exception:
                            pass

    raw_num = pd.to_numeric(df[raw_col].astype(str).str.replace(',', ''), errors='coerce')
    proj = (raw_num / SAMPLE_CAP) * US_POPULATION
    formatted = []
    for p in proj:
        if pd.isna(p):
            formatted.append('')
        else:
            formatted.append(f"{int(round(p))}")
    df['US Gen Pop Projection'] = formatted

    # Place projected sample size (from SAMPLE SIZE row, col D) in BRAND INPUT row (col F)
    sample_size_val = None
    if sample_size_mask.any():
        for idx in df[sample_size_mask].index:
            for col in [raw_col, 'Category Share', 'Percentage']:
                if col in df.columns:
                    val = df.at[idx, col]
                    try:
                        v = float(str(val).replace(',', '').strip())
                        if v > 0:
                            sample_size_val = v
                            break
                    except Exception:
                        pass
            if sample_size_val is not None:
                break

    if sample_size_val is not None:
        projected_sample = int(round((sample_size_val / SAMPLE_CAP) * US_POPULATION))
        brand_input_mask = df['Column'].str.upper() == 'BRAND INPUT'
        if brand_input_mask.any():
            df.loc[brand_input_mask, 'US Gen Pop Projection'] = str(projected_sample)

    return df

def enforce_streaming_platform_top(df: pd.DataFrame) -> pd.DataFrame:
    """Ensure the specified 24 streaming platforms are always in the top 9 positions of STREAMING/PLATFORM.
    
    The 24 platforms are:
    NETFLIX, HULU, DISNEY+, AMAZON PRIME VIDEO, HBO MAX, PARAMOUNT+, YOUTUBE KIDS, 
    PEACOCK, SPORTS NET, TELEMUNDO, PPV, CHEDDAR TV, APPLE TV+, DAZN, SLING PLATFORM,
    VIX, ANGEL TV, KOCOWA+, HAYSTACK NEWS, ULLU, ACORN TV, TENNIS TV, TRILLERTV, ESPN
    
    Positioning among these 24 is organic based on their natural percentages.
    """
    if df is None or df.empty:
        return df
    
    df = df.copy()
    
    # Define the 24 platforms that must be in top 9
    top_streaming_platforms = {
        'NETFLIX', 'HULU', 'DISNEY+', 'AMAZON PRIME VIDEO', 'HBO MAX', 'PARAMOUNT+',
        'YOUTUBE KIDS', 'PEACOCK', 'SPORTS NET', 'TELEMUNDO', 'PPV', 'CHEDDAR TV',
        'APPLE TV+', 'DAZN', 'SLING PLATFORM', 'VIX', 'ANGEL TV', 'KOCOWA+',
        'HAYSTACK NEWS', 'ULLU', 'ACORN TV', 'TENNIS TV', 'TRILLERTV', 'ESPN'
    }
    
    # Find STREAMING/PLATFORM category
    streaming_mask = df['Column'].str.upper() == 'STREAMING/PLATFORM'
    if not streaming_mask.any():
        if not SILENCE_VERBOSE_OUTPUT:
            print("  ℹ️  No STREAMING/PLATFORM category found")
        return df
    
    streaming_df = df[streaming_mask].copy()
    
    if len(streaming_df) == 0:
        if not SILENCE_VERBOSE_OUTPUT:
            print("  ℹ️  No entries found in STREAMING/PLATFORM")
        return df
    
    # Convert percentages to float for sorting
    streaming_df['Percentage'] = pd.to_numeric(streaming_df['Percentage'], errors='coerce').fillna(0)
    
    # Sort by percentage descending
    streaming_sorted = streaming_df.sort_values('Percentage', ascending=False)
    
    # Find which of our 24 platforms are present and their current positions
    platform_positions = {}
    for idx, row in streaming_sorted.iterrows():
        value_upper = str(row['Value']).upper().strip()
        
        # Check for exact matches and common variations
        for platform in top_streaming_platforms:
            if (value_upper == platform or
                value_upper == platform.replace('+', ' PLUS') or
                value_upper == platform.replace('+', 'PLUS') or
                (platform == 'HBO MAX' and value_upper in ['MAX', 'HBO MAX']) or
                (platform == 'YOUTUBE KIDS' and value_upper in ['YOUTUBE KID', 'YOUTUBE KIDS']) or
                (platform == 'SLING PLATFORM' and value_upper in ['SLING', 'SLING PLATFO', 'SLING PLATFORM']) or
                (platform == 'HAYSTACK NEWS' and value_upper in ['HAYSTACK N', 'HAYSTACK NEWS']) or
                (platform == 'CHEDDAR TV' and value_upper in ['CHEDDAR TV', 'CHEDDAR']) or
                (platform == 'APPLE TV+' and value_upper in ['APPLE TV+', 'APPLE TV PLUS', 'APPLE TV']) or
                (platform == 'PARAMOUNT+' and value_upper in ['PARAMOUNT+', 'PARAMOUNT PLUS', 'PARAMOUNT']) or
                (platform == 'DISNEY+' and value_upper in ['DISNEY+', 'DISNEY PLUS', 'DISNEY'])):
                
                current_position = len(platform_positions) + 1
                platform_positions[platform] = {
                    'idx': idx,
                    'current_position': current_position,
                    'percentage': row['Percentage']
                }
                break
    
    if not platform_positions:
        if not SILENCE_VERBOSE_OUTPUT:
            print("  ℹ️  None of the specified 24 platforms found in STREAMING/PLATFORM")
        return df
    
    # Sort platforms by their current percentage (organic positioning)
    sorted_platforms = sorted(platform_positions.items(), 
                            key=lambda x: x[1]['percentage'], reverse=True)
    
    # Ensure these platforms are in positions 1-9 (or as many as we have)
    target_positions = min(9, len(sorted_platforms))
    adjustments_made = 0
    
    for i in range(target_positions):
        platform_name, platform_data = sorted_platforms[i]
        current_position = platform_data['current_position']
        
        if current_position > 9:
            # This platform needs to be moved into top 9
            target_position = i + 1
            
            # Find what's currently at the target position
            if len(streaming_sorted) >= target_position:
                current_at_target_idx = streaming_sorted.index[target_position - 1]
                current_at_target_pct = df.loc[current_at_target_idx, 'Percentage']
                
                # Set the platform to be higher than what's at the target position
                new_pct = float(current_at_target_pct) + 0.5
                df.loc[platform_data['idx'], 'Percentage'] = new_pct
                
                if not SILENCE_VERBOSE_OUTPUT:
                    print(f"  🔧 MOVED {platform_name} to top 9 in STREAMING/PLATFORM: position {current_position} → position {target_position} ({new_pct:.2f}%)")
                adjustments_made += 1
    
    # Re-sort the category to ensure proper ordering
    streaming_df_updated = df[streaming_mask].copy()
    streaming_df_updated['Percentage'] = pd.to_numeric(streaming_df_updated['Percentage'], errors='coerce').fillna(0)
    streaming_sorted_updated = streaming_df_updated.sort_values('Percentage', ascending=False)
    
    # Apply the new ordering to the main dataframe
    for i, (_, row) in enumerate(streaming_sorted_updated.iterrows()):
        df.loc[row.name, 'Percentage'] = row['Percentage']
    
    if not SILENCE_VERBOSE_OUTPUT and adjustments_made > 0:
        print(f"  ✅ STREAMING/PLATFORM positioning: {adjustments_made} platforms moved to top 9")
    
    return df

def rename_streaming_max_to_hbo_max_upper(df: pd.DataFrame) -> pd.DataFrame:
    """Rename any 'Max' variants to 'HBO MAX' within STREAMING/PLATFORM(S)."""
    import pandas as pd
    if df is None or df.empty:
        return df
    df = df.copy()
    cat_mask = df['Column'].astype(str).str.upper().isin(['STREAMING/PLATFORM', 'STREAMING/PLATFORMS'])
    if not cat_mask.any():
        return df
    val_mask = df.loc[cat_mask, 'Value'].astype(str).str.strip().str.lower().isin(['max', 'hbo max'])
    idxs = df.loc[cat_mask].index[val_mask]
    if len(idxs) > 0:
        df.loc[idxs, 'Value'] = 'HBO MAX'
    return df

def ensure_streaming_platforms_presence(df: pd.DataFrame) -> pd.DataFrame:
    """Ensure all canonical streaming platforms are present in STREAMING/PLATFORM(S).

    If a platform is missing, insert a row with a tiny percentage and minimal raws
    so it appears in the output and can be prioritized by ordering rules.
    """
    import pandas as pd
    if df is None or df.empty:
        return df
    df = df.copy()
    platforms = [
        'NETFLIX', 'HULU', 'DISNEY+', 'HBO MAX', 'MAX', 'APPLE TV+', 'PEACOCK',
        'PARAMOUNT+', 'ESPN', 'AMAZON PRIME VIDEO'
    ]
    # Consider both label variants; resolve a single Series aligned to df.index
    if 'Column' in df.columns:
        col_obj = df['Column']
        col_series = col_obj.iloc[:, 0] if isinstance(col_obj, pd.DataFrame) else col_obj
    else:
        col_idx = [i for i, c in enumerate(df.columns) if c == 'Column']
        if not col_idx:
            return df
        col_series = df.iloc[:, col_idx[0]]
    col_upper = col_series.astype(str).str.upper().tolist()
    cat_indices = [i for i, v in enumerate(col_upper) if v in ['STREAMING/PLATFORM', 'STREAMING/PLATFORMS']]
    # Get sample size for small raw seed
    # Resolve SAMPLE SIZE safely
    sample_col = col_series
    sample_upper = sample_col.astype(str).str.upper().tolist()
    sample_indices = [i for i, v in enumerate(sample_upper) if v == 'SAMPLE SIZE']
    sample_size = None
    if sample_indices:
        try:
            sample_val = df.iloc[sample_indices[0]]['Percentage']
            sample_size = int(float(str(sample_val).replace(',', '')))
        except Exception:
            sample_size = None
    seed_raw = 1
    if sample_size and sample_size > 0:
        seed_raw = max(1, int(round(sample_size * 0.00001)))  # 0.001% of sample
    # Insert missing rows
    for name in platforms:
        name_up = name.upper()
        exists = False
        if cat_indices:
            seg = df.iloc[cat_indices].copy()
            # Safely resolve the 'Value' column even if duplicated
            if 'Value' in seg.columns:
                val_obj = seg['Value']
                if isinstance(val_obj, pd.DataFrame):
                    val_series = val_obj.iloc[:, 0]
                else:
                    val_series = val_obj
                exists = val_series.astype(str).str.upper().str.strip().eq(name_up).any()
            else:
                exists = False
        if not exists:
            new_row = {
                'Column': 'STREAMING/PLATFORM',
                'Value': name_up,
                'Percentage': 0.0001,  # tiny non-zero to allow ordering
                'Original Raw Numbers': str(seed_raw),
                'Original Raw Numbers (Database)': str(seed_raw)
            }
            df = pd.concat([df, pd.DataFrame([new_row])], ignore_index=True)
    # Normalize naming immediately
    df = rename_streaming_max_to_hbo_max_upper(df)
    return df

def cleanup_streaming_platforms(df: pd.DataFrame) -> pd.DataFrame:
    """Remove YouTube TV from STREAMING/PLATFORM(S) and dedupe HBO MAX to a single entry.

    - Drops rows where Column is STREAMING/PLATFORM(S) and Value equals YOUTUBE TV or YOUTUBE
    - Keeps Amazon Prime Video in STREAMING/PLATFORM category
    - If multiple HBO MAX rows exist, keeps the one with highest Percentage, drops others
    """
    import pandas as pd
    if df is None or df.empty:
        return df
    df = df.copy()
    col_up = df['Column'].astype(str).str.upper()
    is_streaming = col_up.isin(['STREAMING/PLATFORM', 'STREAMING/PLATFORMS'])
    if not is_streaming.any():
        return df
    # Drop YouTube TV from streaming platforms (but keep Amazon Prime Video)
    val_up = df['Value'].astype(str).str.upper().str.strip()
    drop_mask = is_streaming & (val_up.isin(['YOUTUBE TV', 'YOUTUBE']))
    if drop_mask.any():
        df = df.loc[~drop_mask].copy()
    # Dedupe HBO MAX: keep highest Percentage
    is_hbo = is_streaming & (val_up.isin(['HBO MAX', 'MAX']))
    if is_hbo.any():
        seg = df.loc[is_hbo].copy()
        seg['PCT'] = pd.to_numeric(seg['Percentage'], errors='coerce').fillna(0.0)
        # Pick index of max percentage
        keep_idx = seg['PCT'].idxmax()
        drop_idxs = [i for i in seg.index if i != keep_idx]
        if drop_idxs:
            df = df.drop(index=drop_idxs)
        # Normalize the remaining label to HBO MAX
        df.at[keep_idx, 'Value'] = 'HBO MAX'
    return df
def enforce_social_media_not_top4(df):
    """Ensure TWITCH, DISCORD, BLUESKY are never in top 4 of SOCIAL MEDIA.
    If any are in top 4, reduce their Percentage just below the 4th highest
    non-excluded brand (or a small floor if unavailable)."""
    

    category_mask = df['Column'].str.upper() == 'SOCIAL MEDIA'
    if not category_mask.any():
        return df

    social_idx = df[category_mask].index
    social_df = df.loc[social_idx].copy()
    social_df['Percentage'] = pd.to_numeric(social_df['Percentage'], errors='coerce')

    # Excluded brands (TUMBLR no longer excluded)
    excluded = ['twitch', 'discord', 'bluesky']
    def is_excluded(val: str) -> bool:
        sval = str(val).lower()
        return any(x in sval for x in excluded)

    # Sort by percentage descending
    sorted_df = social_df.sort_values('Percentage', ascending=False)

    # Determine 4th highest allowed (non-excluded) threshold
    allowed_sorted = sorted_df[~sorted_df['Value'].apply(is_excluded)]
    if len(allowed_sorted) >= 4:
        threshold = float(allowed_sorted.iloc[3]['Percentage'])
    elif len(allowed_sorted) >= 1:
        # If fewer than 4 allowed, use the smallest allowed as threshold
        threshold = float(allowed_sorted.iloc[-1]['Percentage'])
    else:
        # No allowed values found; use near-zero to push excluded down
        threshold = 0.01

    epsilon = max(1e-4, threshold * 1e-4)

    # Adjust any excluded brands currently in top 4
    top4 = sorted_df.head(4)
    for idx in top4.index:
        val = sorted_df.at[idx, 'Value']
        if is_excluded(val):
            current = float(sorted_df.at[idx, 'Percentage']) if not pd.isna(sorted_df.at[idx, 'Percentage']) else 0.0
            new_val = max(0.01, threshold - epsilon)
            if current > new_val:
                df.at[idx, 'Percentage'] = new_val

    return df

def enforce_social_media_top4(df):
    """Ensure TIKTOK, FACEBOOK, YOUTUBE, INSTAGRAM are in top 4 of SOCIAL MEDIA.
    Maintains their natural ranking order - just swaps positions if needed."""
    
    category_mask = df['Column'].str.upper() == 'SOCIAL MEDIA'
    if not category_mask.any():
        return df
    
    social_idx = df[category_mask].index
    social_df = df.loc[social_idx].copy()
    social_df['Percentage'] = pd.to_numeric(social_df['Percentage'], errors='coerce')
    
    # Required top 4 brands (case-insensitive)
    required_top4 = ['tiktok', 'facebook', 'youtube', 'instagram']
    
    def is_required(val: str) -> bool:
        sval = str(val).lower()
        return any(brand in sval for brand in required_top4)
    
    # Sort by percentage descending (natural ranking)
    sorted_df = social_df.sort_values('Percentage', ascending=False)
    
    # Find all required brands in the data
    required_brands = sorted_df[sorted_df['Value'].apply(is_required)]
    
    if len(required_brands) < 4:
        # Not all required brands exist, can't enforce
        return df
    
    # Get top 4 positions
    top4_indices = sorted_df.head(4).index.tolist()
    
    # Check if all required brands are in top 4
    required_in_top4 = [idx for idx in required_brands.index if idx in top4_indices]
    
    if len(required_in_top4) == 4:
        # All required brands already in top 4, no action needed
        return df
    
    # Need to swap: find required brands outside top 4 and non-required brands in top 4
    required_outside = [idx for idx in required_brands.index if idx not in top4_indices]
    non_required_in_top4 = [idx for idx in top4_indices if not is_required(df.at[idx, 'Value'])]
    
    # Swap percentages to move required brands into top 4
    # Sort both lists by percentage to maintain relative order
    required_outside_sorted = sorted(required_outside, key=lambda i: float(df.at[i, 'Percentage']), reverse=True)
    non_required_sorted = sorted(non_required_in_top4, key=lambda i: float(df.at[i, 'Percentage']))
    
    swaps = min(len(required_outside_sorted), len(non_required_sorted))
    for i in range(swaps):
        req_idx = required_outside_sorted[i]
        non_req_idx = non_required_sorted[i]
        # Swap their percentages
        temp = df.at[req_idx, 'Percentage']
        df.at[req_idx, 'Percentage'] = df.at[non_req_idx, 'Percentage']
        df.at[non_req_idx, 'Percentage'] = temp
        if not SILENCE_VERBOSE_OUTPUT:
            print(f"🔄 Swapped {df.at[req_idx, 'Value']} into top 4 of SOCIAL MEDIA")

    return df

def enforce_twitch_cap_social(df):
    """Clamp TWITCH in SOCIAL MEDIA to the range [2, 8] percent."""
    import pandas as pd
    mask = (df['Column'].str.upper() == 'SOCIAL MEDIA') & (
        df['Value'].str.contains('twitch', case=False, na=False)
    )
    if not mask.any():
        return df
    df.loc[mask, 'Percentage'] = pd.to_numeric(df.loc[mask, 'Percentage'], errors='coerce')
    df.loc[mask, 'Percentage'] = df.loc[mask, 'Percentage'].clip(lower=2.0, upper=8.0)
    return df

def ensure_percentage_four_decimals(df):
    """
    Ensure the 'Percentage' column is numeric and formatted to 4 decimal places.
    Keeps non-numeric entries as-is (but normally everything should be numeric here).
    """
    import pandas as pd
    if 'Percentage' not in df.columns:
        return df
    s = pd.to_numeric(df['Percentage'], errors='coerce')
    # Fallback zeros for NaNs
    s = s.fillna(0.0)
    df['Percentage'] = s.map(lambda x: f"{float(x):.4f}")
    return df


def normalize_output_text_values(df):
    """
    Final text hygiene:
    - remove mojibake / smart-punctuation artifacts from Value labels
    - standardize AGE bucket labels to canonical ASCII output
    """
    import re
    if 'Value' not in df.columns or 'Column' not in df.columns:
        return df

    out = df.copy()
    replacements = {
        '‚Äì': '-',
        'â€“': '-',
        '–': '-',
        '—': '-',
        'â€”': '-',
        '‑': '-',
        '‚Äô': "'",
        'â€™': "'",
        '’': "'",
        'Â': '',
    }

    def _clean(s):
        text = str(s)
        for bad, good in replacements.items():
            text = text.replace(bad, good)
        text = re.sub(r'\s+', ' ', text).strip()
        return text

    def _canonical_age_label(s):
        t = _clean(s).upper()
        t = re.sub(r'\s*-\s*', '-', t)
        age_map = {
            '17 AND UNDER': '17 AND UNDER',
            '17-UNDER': '17 AND UNDER',
            'UNDER 17': '17 AND UNDER',
            'UNDER17': '17 AND UNDER',
            '18-24': '18-24',
            '25-34': '25-34',
            '35-44': '35-44',
            '45-54': '45-54',
            '55-64': '55-64',
            '65+': '65 OR OLDER',
            '65 OR OLDER': '65 OR OLDER',
        }
        return age_map.get(t, _clean(s))

    value_series = out['Value'].map(_clean)
    age_mask = out['Column'].astype(str).str.upper().str.strip() == 'AGE'
    value_series.loc[age_mask] = value_series.loc[age_mask].map(_canonical_age_label)
    out['Value'] = value_series
    return out

def enforce_max_four_decimals_across_columns(df):
    """
    Ensure numeric-like fields are formatted with at most 4 decimal places.
    Applies to columns commonly holding numbers as strings.
    """
    import pandas as pd
    import re
    numeric_like_cols = [
        'Percentage',
        'Brand Penetration (Row)',
        'Category Share',
        'Original Raw Numbers',
        'Original Raw Numbers (Database)',
        'Estimated Raw Numbers (From Final %)',
        'Unique Purchase Confirmations',
        'Raw Numbers'
    ]
    for col in numeric_like_cols:
        if col not in df.columns:
            continue
        # Coerce to numeric where possible
        series = pd.to_numeric(df[col].astype(str).str.replace(',', ''), errors='coerce')
        formatted = []
        for orig, num in zip(df[col].astype(str), series):
            if pd.isna(num):
                formatted.append(orig)
            else:
                if col == 'Original Raw Numbers':
                    formatted.append(str(int(round(num))) if num == int(num) else f"{num:.4f}")
                else:
                    formatted.append(f"{num:.4f}")
        df[col] = formatted
    return df


def enforce_no_perfect_trailing_zeros(df):
    """
    Final anti-templating formatter (all non-metadata categories):
    - Avoid exact x.0000 style values.
    - Break exact duplicate 4dp values within each category.
    - Reduce repeated 4-digit decimal suffix clustering for organic look.
    - Keep each category total stable via anchor compensation.
    """
    import pandas as pd

    if 'Column' not in df.columns:
        return df

    out = df.copy()
    target_col = 'Brand Penetration (Row)' if 'Brand Penetration (Row)' in out.columns else None
    if not target_col:
        if 'Category Share' in out.columns:
            target_col = 'Category Share'
        elif 'Percentage' in out.columns:
            target_col = 'Percentage'
        else:
            return out

    # Only mutate the selected target metric. Derived metrics are recalculated
    # downstream from BP (same contract as edit_sample_size.py).
    sync_cols = [target_col]
    meta_cols = {
        'INPUT_METADATA', 'SAMPLE SIZE', 'BRAND INPUT', 'AVID FAN', 'CASUAL FAN', 'BRAND CATEGORY'
    }

    def _to_num(v):
        try:
            return float(str(v).replace(',', '').replace('%', '').strip())
        except Exception:
            return 0.0

    def _is_perfect_4dp(v):
        # True when value ends with .0000 at 4-decimal precision.
        return f"{float(v):.4f}".endswith('.0000')

    touched = 0
    cat_keys = out['Column'].astype(str).str.upper().str.strip()
    for cat in cat_keys.unique():
        if cat in meta_cols:
            continue
        mask = cat_keys == cat
        idxs = list(out[mask].index)
        if not idxs:
            continue

        vals = {i: round(_to_num(out.at[i, target_col]), 4) for i in idxs}

        # Build de-templating targets:
        # 1) perfect *.0000 values
        # 2) exact duplicate values (all but first)
        # 3) repeated suffixes (all but first)
        # 4) tidy/templated suffixes often produced by small-step nudges
        tidy_suffixes = {'0000', '0001', '9999', '5000', '2500', '7500', '0098'}
        perfect = [i for i in idxs if _is_perfect_4dp(vals[i]) and vals[i] >= 0]

        duplicate_value_targets = []
        dup_groups = {}
        for i in idxs:
            dup_groups.setdefault(vals[i], []).append(i)
        for _v, members in dup_groups.items():
            if len(members) > 1:
                duplicate_value_targets.extend(members[1:])

        repeated_suffix_targets = []
        suffix_groups = {}
        for i in idxs:
            suf = f"{vals[i]:.4f}".split('.')[-1]
            suffix_groups.setdefault(suf, []).append(i)
        for _suf, members in suffix_groups.items():
            if len(members) > 1:
                repeated_suffix_targets.extend(members[1:])

        tidy_suffix_targets = []
        for i in idxs:
            suf = f"{vals[i]:.4f}".split('.')[-1]
            if suf in tidy_suffixes:
                tidy_suffix_targets.append(i)

        to_adjust = []
        seen = set()
        for i in (perfect + duplicate_value_targets + repeated_suffix_targets + tidy_suffix_targets):
            if i in seen:
                continue
            seen.add(i)
            to_adjust.append(i)

        if not to_adjust:
            continue

        original_total = round(sum(vals[i] for i in idxs), 4)
        compensation = 0.0
        adjusted = set()
        for pos, i in enumerate(to_adjust):
            old = round(vals[i], 4)
            # Do not disturb intentional near-100 rows.
            if old >= 99.99:
                continue
            # Deterministic 0.0001..0.0097 spread for organic decimals.
            delta = ((abs(hash(f"deround4|{cat}|{i}|{pos}")) % 97) + 1) / 10000.0
            sign = 1.0 if (abs(hash(f"deround4sign|{cat}|{i}|{pos}")) % 2) else -1.0
            if vals[i] <= delta + 0.0001:
                sign = 1.0
            new = round(max(0.0001, min(99.9999, old + sign * delta)), 4)
            if new == old:
                new = round(min(99.9999, old + 0.0001), 4)
            vals[i] = new
            compensation = round(compensation + (new - old), 4)
            adjusted.add(i)
            touched += 1

        # Offset drift from largest non-adjusted row (or largest row overall).
        candidates = [i for i in idxs if i not in adjusted] or idxs
        anchor = max(candidates, key=lambda i: vals[i])
        vals[anchor] = round(max(0.0001, vals[anchor] - compensation), 4)

        # Suffix de-cluster pass: prefer unique suffixes within each category.
        suffix_owner = {}
        suffix_comp = 0.0
        for i in sorted(idxs, key=lambda k: (-vals[k], k)):
            old = round(vals[i], 4)
            if old >= 99.99:
                suf = f"{old:.4f}".split('.')[-1]
                suffix_owner.setdefault(suf, i)
                continue
            s_old = f"{old:.4f}".split('.')[-1]
            if s_old not in suffix_owner and s_old not in tidy_suffixes:
                suffix_owner[s_old] = i
                continue

            placed = False
            for attempt in range(1, 80):
                delta = ((abs(hash(f"suffix-reassign|{cat}|{i}|{attempt}")) % 97) + 1) / 10000.0
                sign = 1.0 if (abs(hash(f"suffix-reassign-sign|{cat}|{i}|{attempt}")) % 2) else -1.0
                if old <= delta + 0.0001:
                    sign = 1.0
                cand = round(max(0.0001, min(99.9999, old + sign * delta)), 4)
                s_cand = f"{cand:.4f}".split('.')[-1]
                if s_cand not in suffix_owner and s_cand not in tidy_suffixes:
                    vals[i] = cand
                    suffix_owner[s_cand] = i
                    suffix_comp = round(suffix_comp + (cand - old), 4)
                    placed = True
                    touched += 1
                    break
            if not placed:
                suffix_owner.setdefault(s_old, i)

        if abs(suffix_comp) > 0:
            vals[anchor] = round(max(0.0001, vals[anchor] - suffix_comp), 4)

        # Final drift correction at 4dp precision.
        new_total = round(sum(vals[i] for i in idxs), 4)
        drift = round(original_total - new_total, 4)
        if abs(drift) > 0:
            vals[anchor] = round(max(0.0001, vals[anchor] + drift), 4)

        # Write back and synchronize percentage-like columns.
        for i in idxs:
            s = f"{vals[i]:.4f}"
            for c in sync_cols:
                out.at[i, c] = s

    if touched and not SILENCE_VERBOSE_OUTPUT:
        print(f"🎚️ Anti-rounding guard: de-rounded {touched} value(s) ending in .0000")
    return out

def cap_original_raw_numbers_to_sample_size(df):
    """
    Ensure 'Original Raw Numbers (Database)' never exceeds the SAMPLE SIZE.
    Applies to all behavioral rows (excludes metadata/derived categories).
    Keeps values as strings to match CSV output style.
    """
    import pandas as pd

    db_col = 'Original Raw Numbers (Database)'
    if db_col not in df.columns:
        return df

    # Resolve sample size from SAMPLE SIZE row
    sample_mask = df['Column'].str.upper() == 'SAMPLE SIZE'
    if not sample_mask.any():
        return df
    sample_size = None
    for _ss_col in ['Original Raw Numbers', 'Category Share', 'Percentage']:
        if _ss_col not in df.columns:
            continue
        try:
            _ss_v = int(float(str(df.loc[sample_mask, _ss_col].iloc[0]).replace(',', '')))
            if _ss_v > 1000:
                sample_size = _ss_v
                break
        except Exception:
            continue
    if not sample_size:
        return df

    # Rows to exclude from capping
    excluded_columns = set(['INPUT_METADATA', 'SAMPLE SIZE', 'PURCHASE SHARE', 'BRAND PENETRATION'])

    for idx, row in df.iterrows():
        column_name = str(row.get('Column', '')).upper()
        if column_name in excluded_columns:
            continue
        # Allow INTEREST/INTERESTS to exceed sample size
        if column_name in ['INTEREST', 'INTERESTS']:
            continue
        raw_val = row.get(db_col, '')
        try:
            raw_num = int(float(str(raw_val).replace(',', ''))) if raw_val not in (None, '', 'nan', 'NaN') else None
        except Exception:
            raw_num = None
        if raw_num is None:
            continue
        if raw_num > sample_size:
            df.at[idx, db_col] = str(sample_size)

    return df

